// KV Cache Service with intelligent TTL strategies

import type { Env } from '../types';
import { ValidationUtils, ErrorHandler } from '../../../../services/shared';

export class CacheService {
  constructor(private env: Env) {}
  
  // Cache TTL strategies (in seconds)
  private readonly TTL = {
    HOT: 60,           // 1 minute - frequently changing data
    FEED: 300,         // 5 minutes - feed data
    PROFILE: 600,      // 10 minutes - user profiles
    STATIC: 3600,      // 1 hour - relatively static data
    LONG: 86400,       // 24 hours - rarely changing data
  };
  
  /**
   * Get cached value
   */
  async get<T>(key: string): Promise<T | null> {
    try {
      const value = await this.env.CACHE.get(key, 'json');
      return value as T | null;
    } catch (error) {
      console.error('Cache get error:', error);
      return null;
    }
  }
  
  /**
   * Set cached value with TTL
   */
  async set(
    key: string,
    value: any,
    ttl: number = this.TTL.FEED
  ): Promise<void> {
    try {
      await this.env.CACHE.put(key, JSON.stringify(value), {
        expirationTtl: ttl,
      });
    } catch (error) {
      console.error('Cache set error:', error);
    }
  }
  
  /**
   * Delete cached value
   */
  async delete(key: string): Promise<void> {
    try {
      await this.env.CACHE.delete(key);
    } catch (error) {
      console.error('Cache delete error:', error);
    }
  }
  
  /**
   * Cache user profile
   */
  async cacheUserProfile(userId: string, profile: any): Promise<void> {
    await this.set(`user:${userId}`, profile, this.TTL.PROFILE);
  }
  
  /**
   * Get cached user profile
   */
  async getUserProfile(userId: string): Promise<any | null> {
    return await this.get(`user:${userId}`);
  }
  
  /**
   * Cache video metadata
   */
  async cacheVideo(videoId: string, video: any): Promise<void> {
    await this.set(`video:${videoId}`, video, this.TTL.STATIC);
  }
  
  /**
   * Get cached video
   */
  async getVideo(videoId: string): Promise<any | null> {
    return await this.get(`video:${videoId}`);
  }
  
  /**
   * Cache For You feed
   */
  async cacheFeed(userId: string | null, videos: any[]): Promise<void> {
    const key = userId ? `feed:foryou:${userId}` : 'feed:foryou:anonymous';
    await this.set(key, videos, this.TTL.FEED);
  }
  
  /**
   * Get cached feed
   */
  async getFeed(userId: string | null): Promise<any[] | null> {
    const key = userId ? `feed:foryou:${userId}` : 'feed:foryou:anonymous';
    return await this.get(key);
  }
  
  /**
   * Invalidate user cache (on profile update)
   */
  async invalidateUser(userId: string): Promise<void> {
    await this.delete(`user:${userId}`);
  }
  
  /**
   * Invalidate video cache (on update/delete)
   */
  async invalidateVideo(videoId: string): Promise<void> {
    await this.delete(`video:${videoId}`);
  }
  
  /**
   * Invalidate feed cache (on new video upload)
   */
  async invalidateFeed(userId: string | null): Promise<void> {
    const key = userId ? `feed:foryou:${userId}` : 'feed:foryou:anonymous';
    await this.delete(key);
  }
  
  /**
   * Get or set with cache-aside pattern
   */
  async getOrSet<T>(
    key: string,
    fetchFn: () => Promise<T>,
    ttl: number = this.TTL.FEED
  ): Promise<T> {
    // Try cache first
    const cached = await this.get<T>(key);
    if (cached !== null) {
      return cached;
    }
    
    // Cache miss - fetch and store
    const value = await fetchFn();
    await this.set(key, value, ttl);
    return value;
  }
}
