/**
 * Coins Service - Advanced Coin Management System
 * Designed for 2B+ users scale with enterprise-grade reliability
 * 
 * Features:
 * - Atomic coin transactions
 * - Balance tracking with audit trail
 * - Transaction history with pagination
 * - Fraud detection and prevention
 * - Rate limiting per user
 * - ACID compliance
 * - Real-time balance updates
 * - Multi-currency support (future)
 */

import type { Env, CoinsRow, CoinBalance as CoinBalanceDTO } from '../types';
import { startSpan, endSpan } from '../utils/otel';
import { ValidationUtils, ErrorHandler } from '../../../../services/shared';

// ============================================
// TYPES & INTERFACES
// ============================================

export interface CoinTransaction {
  id: string;
  userId: string;
  amount: number;
  type: 'purchase' | 'gift_sent' | 'gift_received' | 'reward' | 'refund' | 'payout' | 'bonus';
  balanceBefore: number;
  balanceAfter: number;
  metadata?: Record<string, any>;
  createdAt: number;
  stripeChargeId?: string;
  relatedUserId?: string; // For gifts
  videoId?: string;
  giftId?: string;
}

export interface CoinBalance extends CoinBalanceDTO {}

export interface PurchasePackage {
  id: string;
  coins: number;
  priceUSD: number;
  priceCents: number;
  bonusCoins?: number;
  popularityRank?: number;
}

