// Database service with dual-mode support (D1 primary, Firestore fallback)

import type { Env, User, Video } from '../types';
import { ValidationUtils, ErrorHandler } from '../../../../services/shared';

export class DatabaseService {
  constructor(private env: Env) {}
  
  // User operations
  async createUser(user: Omit<User, 'id' | 'createdAt' | 'updatedAt'>): Promise<User> {
    const id = crypto.randomUUID();
    const now = new Date().toISOString();
    
    const fullUser: User = {
      id,
      ...user,
      followersCount: 0,
      followingCount: 0,
      likesCount: 0,
      isVerified: false,
      isPremium: false,
      createdAt: now,
      updatedAt: now,
    };
    
    try {
      await this.env.DB.prepare(
        `INSERT INTO users (id, username, email, password_hash, display_name, bio, avatar_url, 
         followers_count, following_count, likes_count, is_verified, is_premium, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(
        id,
        fullUser.username,
        fullUser.email,
        fullUser.passwordHash,
        fullUser.displayName,
        fullUser.bio || null,
        fullUser.avatarUrl || null,
        0, 0, 0,
        false,
        false,
        now,
        now
      ).run();
      
      return fullUser;
    } catch (error) {
      console.error('D1 createUser error:', error);
      // TODO: Fallback to Firestore
      throw error;
    }
  }
  
  async getUserByEmail(email: string): Promise<User | null> {
    try {
      const result = await this.env.DB.prepare(
        'SELECT * FROM users WHERE email = ?'
      ).bind(email).first();
      
      if (!result) return null;
      
      return this.mapDbRowToUser(result);
    } catch (error) {
      console.error('D1 getUserByEmail error:', error);
      return null;
    }
  }
  
  async getUserById(id: string): Promise<User | null> {
    try {
      const result = await this.env.DB.prepare(
        'SELECT * FROM users WHERE id = ?'
      ).bind(id).first();
      
      if (!result) return null;
      
      return this.mapDbRowToUser(result);
    } catch (error) {
      console.error('D1 getUserById error:', error);
      return null;
    }
  }
  
  // Video operations
  async createVideo(video: Omit<Video, 'id' | 'createdAt' | 'updatedAt'>): Promise<Video> {
    const id = crypto.randomUUID();
    const now = new Date().toISOString();
    
    const fullVideo: Video = {
      id,
      ...video,
      viewsCount: 0,
      likesCount: 0,
      commentsCount: 0,
      sharesCount: 0,
      processingStatus: 'pending',
      createdAt: now,
      updatedAt: now,
    };
    
    try {
      await this.env.DB.prepare(
        `INSERT INTO videos (id, user_id, title, description, video_url, thumbnail_url, 
         duration, width, height, views_count, likes_count, comments_count, shares_count, 
         hashtags, processing_status, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(
        id,
        fullVideo.userId,
        fullVideo.title,
        fullVideo.description || null,
        fullVideo.videoUrl,
        fullVideo.thumbnailUrl,
        fullVideo.duration,
        fullVideo.width,
        fullVideo.height,
        0, 0, 0, 0,
        fullVideo.hashtags ? JSON.stringify(fullVideo.hashtags) : null,
        'pending',
        now,
        now
      ).run();
      
      return fullVideo;
    } catch (error) {
      console.error('D1 createVideo error:', error);
      throw error;
    }
  }
  
  async getVideosForFeed(limit: number = 20, cursor?: string): Promise<Video[]> {
    try {
      const query = cursor
        ? `SELECT * FROM videos WHERE processing_status = 'ready' AND created_at < ? 
           ORDER BY created_at DESC LIMIT ?`
        : `SELECT * FROM videos WHERE processing_status = 'ready' 
           ORDER BY created_at DESC LIMIT ?`;
      
      const stmt = cursor
        ? this.env.DB.prepare(query).bind(cursor, limit)
        : this.env.DB.prepare(query).bind(limit);
      
      const result = await stmt.all();
      
      return result.results.map((row: Record<string, any>) => this.mapDbRowToVideo(row));
    } catch (error) {
      console.error('D1 getVideosForFeed error:', error);
      return [];
    }
  }
  
  // Helper methods
  private mapDbRowToUser(row: any): User {
    return {
      id: row.id,
      username: row.username,
      email: row.email,
      passwordHash: row.password_hash,
      displayName: row.display_name,
      bio: row.bio,
      avatarUrl: row.avatar_url,
      followersCount: row.followers_count || 0,
      followingCount: row.following_count || 0,
      likesCount: row.likes_count || 0,
      isVerified: Boolean(row.is_verified),
      isPremium: Boolean(row.is_premium),
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
  
  private mapDbRowToVideo(row: any): Video {
    return {
      id: row.id,
      userId: row.user_id,
      title: row.title,
      description: row.description,
      videoUrl: row.video_url,
      thumbnailUrl: row.thumbnail_url,
      duration: row.duration,
      width: row.width,
      height: row.height,
      viewsCount: row.views_count || 0,
      likesCount: row.likes_count || 0,
      commentsCount: row.comments_count || 0,
      sharesCount: row.shares_count || 0,
      hashtags: row.hashtags ? JSON.parse(row.hashtags) : undefined,
      processingStatus: row.processing_status,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
}
