import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { startSpan, endSpan } from '../utils/otel';
import { ensureMinimumAgeRegionAware } from '../utils/guard';
import { logRestrictedAccess } from '../utils/legal_telemetry';
import { ValidationUtils, ErrorHandler, SecurityUtils } from '../../../../services/shared';

function generateCode(): string { return Math.random().toString(36).substring(2, 8); }

// Create referral code for a user
export async function createCode(request: Request, env: Env): Promise<Response> {
  const span = startSpan('referral.create');
  try {
    const body = await request.json().catch(() => ({})) as any;
    const userId = body.userId;
    if (!userId) return jsonResponse(false, null, 'MISSING_USER', 400);
    
    // Region-aware age gating for referral code creation (13+ minimum)
    const ageCheck = await ensureMinimumAgeRegionAware(env, userId, { ip: request.headers.get('cf-connecting-ip') || undefined });
    if (!ageCheck.allowed) {
      await logRestrictedAccess(env, userId, 'referral_code_creation', ageCheck.region, ageCheck.requiredAge, request);
      return jsonResponse(false, null, 'AGE_RESTRICTED', 403);
    }
    const code = generateCode();
    await env.DB.prepare('INSERT INTO referral_codes (code, owner_user_id) VALUES (?1, ?2)')
      .bind(code, userId).run();
    return jsonResponse(true, { code });
  } catch (e: any) {
    return jsonResponse(false, null, 'CODE_ERROR', 500);
  } finally {
    await endSpan(env, span, 'referral.create');
  }
}

// Activate referral code for referred user
export async function activateCode(request: Request, env: Env): Promise<Response> {
  const span = startSpan('referral.activate');
  try {
    const body = await request.json().catch(() => ({})) as any;
    const code = body.code; const referredUserId = body.userId;
    if (!code || !referredUserId) return jsonResponse(false, null, 'INVALID_ACTIVATION', 400);
    
    // Region-aware age gating for referral activation
    const ageCheck = await ensureMinimumAgeRegionAware(env, referredUserId, { ip: request.headers.get('cf-connecting-ip') || undefined });
    if (!ageCheck.allowed) {
      await logRestrictedAccess(env, referredUserId, 'referral_activation', ageCheck.region, ageCheck.requiredAge, request);
      return jsonResponse(false, null, 'AGE_RESTRICTED', 403);
    }
    const existing = await env.DB.prepare('SELECT code FROM referral_codes WHERE code=?1').bind(code).first();
    if (!existing) return jsonResponse(false, null, 'CODE_NOT_FOUND', 404);
    await env.DB.prepare('INSERT INTO referral_activations (code, referred_user_id) VALUES (?1, ?2)')
      .bind(code, referredUserId).run();
    await env.DB.prepare('UPDATE referral_codes SET activations_count = activations_count + 1 WHERE code=?1').bind(code).run();
    return jsonResponse(true, { code, activated: true });
  } catch (_) {
    return jsonResponse(false, null, 'ACTIVATION_ERROR', 500);
  } finally {
    await endSpan(env, span, 'referral.activate');
  }
}

// Stats for a referral code
export async function getStats(request: Request, env: Env): Promise<Response> {
  const span = startSpan('referral.stats');
  try {
    const url = new URL(request.url);
    const code = url.pathname.split('/')[3]; // /referral/stats/:code
    if (!code) return jsonResponse(false, null, 'MISSING_CODE', 400);
    const ref = await env.DB.prepare('SELECT code, owner_user_id, activations_count, created_at FROM referral_codes WHERE code=?1').bind(code).first();
    if (!ref) return jsonResponse(false, null, 'CODE_NOT_FOUND', 404);
    const activations = await env.DB.prepare('SELECT referred_user_id, created_at FROM referral_activations WHERE code=?1 ORDER BY created_at DESC LIMIT 100').bind(code).all();
    return jsonResponse(true, { code: ref.code, owner: ref.owner_user_id, activations_count: ref.activations_count, activations: activations.results || [] });
  } catch (_) {
    return jsonResponse(false, null, 'STATS_ERROR', 500);
  } finally {
    await endSpan(env, span, 'referral.stats');
  }
}
