// Legal Telemetry Hooks - Comprehensive audit trail for GDPR/DSA/COPPA compliance
// Logs all consent changes, data access, erasure requests, age verifications

import type { Env } from '../types';
import { startSpan, endSpan } from '../utils/otel';

export interface LegalEvent {
  userId: string;
  eventType: 'consent_granted' | 'consent_withdrawn' | 'data_accessed' | 'data_erased' | 'age_verified' | 'restricted_access';
  details: Record<string, any>;
  ipAddress?: string;
  userAgent?: string;
  timestamp: number;
}

export async function logLegalEvent(env: Env, event: LegalEvent): Promise<void> {
  const span = startSpan('legal.logEvent', { eventType: event.eventType, userId: event.userId });
  try {
    // Log to D1 for permanent audit trail
    await env.DB.prepare(
      `INSERT INTO legal_audit_log (user_id, event_type, details, ip_address, user_agent, timestamp)
       VALUES (?, ?, ?, ?, ?, ?)`
    ).bind(
      event.userId,
      event.eventType,
      JSON.stringify(event.details),
      event.ipAddress || 'unknown',
      event.userAgent || 'unknown',
      event.timestamp
    ).run();
    
    // Also log to KV for fast recent access (30 day TTL)
    const key = `legal:${event.userId}:${event.eventType}:${event.timestamp}`;
    await env.CACHE.put(key, JSON.stringify(event), { expirationTtl: 2592000 });
    
    console.log(`[LEGAL] ${event.eventType} for user ${event.userId}`, event.details);
  } catch (error) {
    console.error('Failed to log legal event:', error);
    // Never fail primary operation due to logging failure
  } finally {
    await endSpan(env, span, 'legal.log');
  }
}

export async function logConsentChange(
  env: Env,
  userId: string,
  consentType: string,
  granted: boolean,
  request: Request
): Promise<void> {
  await logLegalEvent(env, {
    userId,
    eventType: granted ? 'consent_granted' : 'consent_withdrawn',
    details: { consentType, granted },
    ipAddress: request.headers.get('CF-Connecting-IP') || undefined,
    userAgent: request.headers.get('User-Agent') || undefined,
    timestamp: Date.now(),
  });
}

export async function logDataAccess(
  env: Env,
  userId: string,
  resourceType: string,
  resourceId: string,
  request: Request
): Promise<void> {
  await logLegalEvent(env, {
    userId,
    eventType: 'data_accessed',
    details: { resourceType, resourceId, accessTime: new Date().toISOString() },
    ipAddress: request.headers.get('CF-Connecting-IP') || undefined,
    userAgent: request.headers.get('User-Agent') || undefined,
    timestamp: Date.now(),
  });
}

export async function logDataErasure(
  env: Env,
  userId: string,
  resourceTypes: string[],
  totalRecordsDeleted: number
): Promise<void> {
  await logLegalEvent(env, {
    userId,
    eventType: 'data_erased',
    details: {
      resourceTypes,
      totalRecordsDeleted,
      erasureTime: new Date().toISOString(),
    },
    timestamp: Date.now(),
  });
}

export async function logAgeVerification(
  env: Env,
  userId: string,
  ageClass: string,
  verificationMethod: string,
  request: Request
): Promise<void> {
  await logLegalEvent(env, {
    userId,
    eventType: 'age_verified',
    details: { ageClass, verificationMethod, verifiedAt: new Date().toISOString() },
    ipAddress: request.headers.get('CF-Connecting-IP') || undefined,
    userAgent: request.headers.get('User-Agent') || undefined,
    timestamp: Date.now(),
  });
}

export async function logRestrictedAccess(
  env: Env,
  userId: string,
  reason: string,
  regionOrCountry?: string,
  requiredAge?: number,
  request?: Request
): Promise<void> {
  await logLegalEvent(env, {
    userId,
    eventType: 'restricted_access',
    details: { reason, region: regionOrCountry, requiredAge, blockedAt: new Date().toISOString() },
    ipAddress: request?.headers.get('CF-Connecting-IP') || undefined,
    userAgent: request?.headers.get('User-Agent') || undefined,
    timestamp: Date.now(),
  });
}

export async function getRecentLegalEvents(
  env: Env,
  userId: string,
  eventType?: string,
  limit: number = 100
): Promise<LegalEvent[]> {
  const span = startSpan('legal.getRecent', { userId: String(userId), eventType: eventType ?? 'unknown' });
  try {
    let query = 'SELECT * FROM legal_audit_log WHERE user_id = ?';
    const params: any[] = [userId];
    
    if (eventType) {
      query += ' AND event_type = ?';
      params.push(eventType);
    }
    
    query += ' ORDER BY timestamp DESC LIMIT ?';
    params.push(limit);
    
    const result = await env.DB.prepare(query).bind(...params).all();
    
    return (result.results || []).map((row: any) => ({
      userId: row.user_id,
      eventType: row.event_type,
      details: JSON.parse(row.details || '{}'),
      ipAddress: row.ip_address,
      userAgent: row.user_agent,
      timestamp: row.timestamp,
    }));
  } finally {
    await endSpan(env, span, 'legal.getRecent');
  }
}
