// Main entry point for Cloudflare Workers

import { route, setupRoutes } from './router';
import { recordLatencySample } from './utils/telemetry_exporter';
import { applyMiddleware, addCorsHeaders } from './middleware';
import { handleChatWebSocket } from './ws/chat.websocket';
import { verifyToken } from './utils/jwt.utils';
import { emitRuntimeTelemetry } from './utils/runtime_telemetry';
import { ValidationUtils, ErrorHandler, SecurityUtils } from '../../../services/shared';
import type { Env } from './types';

// Export Durable Objects
export { LiveStream } from './durable/live_stream.do';
export { ChatRoom } from './do/chat-room';

// Initialize routes
setupRoutes();

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const startTime = Date.now();
    const executionId = crypto.randomUUID();
    const reqId = request.headers.get('x-request-id') ?? crypto.randomUUID();
    const flowId = request.headers.get('x-flow-id') ?? `flow-${Date.now()}`;
    const complianceTrace = request.headers.get('x-compliance-trace') ?? `cmp-${Date.now()}`;
    const flowCompliance = request.headers.get('x-flow-compliance') ?? 'true';
    const tracedHeaders = new Headers(request.headers);
    tracedHeaders.set('x-request-id', reqId);
    tracedHeaders.set('x-flow-id', flowId);
    tracedHeaders.set('x-compliance-trace', complianceTrace);
    tracedHeaders.set('x-flow-compliance', flowCompliance);
    const tracedRequest = new Request(request, { headers: tracedHeaders });
    
    try {
      console.log(JSON.stringify({
        layer: 'CF',
        reqId,
        flowId,
        complianceTrace,
        flowCompliance,
        method: tracedRequest.method,
        url: tracedRequest.url,
      }));
      await emitRuntimeTelemetry(env, {
        worker_id: 'w_cf_worker_main',
        execution_id: executionId,
        event: 'START',
        timestamp: new Date().toISOString(),
        duration_ms: null,
        error_code: null,
        error_message: null,
        environment: 'dev',
      }, ctx);
      const upgradeHeader = tracedRequest.headers.get('Upgrade')?.toLowerCase();
      const url = new URL(tracedRequest.url);
      const rawPath = url.pathname.replace(/^\/v1/, '');

      // Fast-path for WebSocket chat: bypass full middleware/instrumentation for latency optimization
      if (upgradeHeader === 'websocket' && rawPath.startsWith('/chat/ws/')) {
        // Minimal auth (Workers JWT only). Region affinity is performance-only; all content remains global.
        const authHeader = tracedRequest.headers.get('Authorization');
        if (!authHeader || !authHeader.startsWith('Bearer ')) {
          return new Response(JSON.stringify({ success:false, error:{ code:'UNAUTHORIZED', message:'Missing auth' } }), { status:401, headers:{'Content-Type':'application/json'} });
        }
        try {
          const token = authHeader.slice(7);
          const payload = await verifyToken(token, env);
          if (payload?.type !== 'access') throw new Error('Invalid token');
        } catch {
          return new Response(JSON.stringify({ success:false, error:{ code:'INVALID_TOKEN', message:'Token verification failed' } }), { status:401, headers:{'Content-Type':'application/json'} });
        }
        // Directly invoke handler (roomId extracted by router normally; replicate extraction)
        const parts = rawPath.split('/');
        const roomId = parts[3] || 'latencyroom';
        // If latencyroom use in-worker optimized handler; else route to global Durable Object to ensure unified content.
        if (roomId === 'latencyroom') {
          const params = { roomId } as any;
          return await handleChatWebSocket(tracedRequest, env, ctx, params);
        }
        if (!env.CHAT_ROOM) {
          return new Response(JSON.stringify({ success:false, error:{ code:'CONFIG_ERROR', message:'CHAT_ROOM namespace missing' } }), { status:500, headers:{'Content-Type':'application/json'} });
        }
        // Multiplex all logical rooms through single global-chat DO to aggregate telemetry
        const id = env.CHAT_ROOM.idFromName('global-chat');
        const stub = env.CHAT_ROOM.get(id);
        return await stub.fetch(tracedRequest);
      }

      // Apply middleware (normal HTTP requests)
      const middlewareResult = await applyMiddleware(tracedRequest, env, ctx);
      if (middlewareResult) return addCorsHeaders(middlewareResult, env);
      
      // Parse URL (already created url above)
      const path = rawPath; // Remove /v1 prefix already handled
      const method = tracedRequest.method;
      
      // Route request
      const response = await route(path, method, tracedRequest, env, ctx);

      // If websocket upgrade, do NOT wrap/clone or we lose webSocket property
      if (response.status === 101 && (response as any).webSocket) {
        // Minimal latency recording (treat as WS upgrade event)
        const duration = Date.now() - startTime;
        try { await recordLatencySample(env, path, duration); } catch {}
        return response; // Return original to preserve upgrade
      }

      // Add response time header for normal HTTP
      const duration = Date.now() - startTime;
      const newHeaders = new Headers(response.headers);
      newHeaders.set('X-Response-Time', `${duration}ms`);

      // Layer D (CF_) edge cache directives per Phase-12 global scaling/edge optimization
      const cacheControl = cacheDirectiveForPath(path);
      if (cacheControl) {
        newHeaders.set('Cache-Control', cacheControl);
      }

      const newResponse = new Response(response.body, { status: response.status, statusText: response.statusText, headers: newHeaders });

      // Record latency sample for in-memory exporter (for performance baseline aggregation)
      try { await recordLatencySample(env, path, duration); } catch { /* non-fatal */ }

      // Log to Analytics Engine
      if (env.ANALYTICS) {
        try {
          env.ANALYTICS.writeDataPoint({
            blobs: [path, method, response.status.toString()],
            doubles: [duration],
            indexes: [env.ENVIRONMENT],
          });
        } catch {/* non-fatal telemetry */}
      }

      const tracedResponse = addCorsHeaders(newResponse, env);
      tracedResponse.headers.set('x-request-id', reqId);
      tracedResponse.headers.set('x-flow-id', flowId);
      tracedResponse.headers.set('x-compliance-trace', complianceTrace);
      tracedResponse.headers.set('x-flow-compliance', flowCompliance);
      await emitRuntimeTelemetry(env, {
        worker_id: 'w_cf_worker_main',
        execution_id: executionId,
        event: 'SUCCESS',
        timestamp: new Date().toISOString(),
        duration_ms: Date.now() - startTime,
        error_code: null,
        error_message: null,
        environment: 'dev',
      }, ctx);
      return tracedResponse;
    } catch (error) {
      console.error('Worker error:', error);
      await emitRuntimeTelemetry(env, {
        worker_id: 'w_cf_worker_main',
        execution_id: executionId,
        event: 'FAILURE',
        timestamp: new Date().toISOString(),
        duration_ms: Date.now() - startTime,
        error_code: 'WORKER_ERROR',
        error_message: error instanceof Error ? error.message : 'unknown_error',
        environment: 'dev',
      }, ctx);
      
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'INTERNAL_ERROR',
            message: 'An unexpected error occurred',
          },
        }),
        {
          status: 500,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
  },
};

// Map route patterns to cache directives (Layer D edge guidance)
function cacheDirectiveForPath(path: string): string | null {
  // Never cache health or integration/compliance/auth
  if (
    path === '/health' ||
    path === '/healthz' ||
    path.startsWith('/backend/health') ||
    path.startsWith('/integration') ||
    path.startsWith('/auth') ||
    path.startsWith('/compliance') ||
    path.startsWith('/backend/compliance-log')
  ) {
    return 'no-store, no-cache, must-revalidate';
  }

  // Feed/public responses: short cache to reduce edge latency without risking staleness
  if (path.startsWith('/feed/')) {
    return 'public, max-age=30, stale-while-revalidate=120';
  }

  // Default: let upstream headers stand
  return null;
}
