import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { startSpan, endSpan } from '../utils/otel';
import { ensureMinimumAgeRegionAware } from '../utils/guard';
import { logDataAccess, logRestrictedAccess } from '../utils/legal_telemetry';
import { detectGiftFraud } from '../utils/fraud_detection';
import { ValidationUtils, ErrorHandler, SecurityUtils } from '../../../../services/shared';

// Helper to get DO stub
function getStub(env: Env, streamId: string) {
  if (!env.LIVE_STREAM) throw new Error('LIVE_STREAM Durable Object not bound');
  const id = env.LIVE_STREAM.idFromName(streamId);
  return env.LIVE_STREAM.get(id);
}

export async function joinStream(request: Request, env: Env): Promise<Response> {
  const url = new URL(request.url);
  const streamId = url.pathname.split('/')[2];
  const userId = url.searchParams.get('userId');
  if (!userId) return jsonResponse(false, null, 'MISSING_USER', 400);
  
  // Region-aware age gating: live streaming requires region-specific minimum age
  const ageCheck = await ensureMinimumAgeRegionAware(env, userId, { ip: request.headers.get('cf-connecting-ip') || undefined });
  if (!ageCheck.allowed) {
    await logRestrictedAccess(env, userId, 'live_stream_join', ageCheck.region, ageCheck.requiredAge, request);
    return jsonResponse(false, null, 'AGE_RESTRICTED', 403);
  }
  const span = startSpan('live.join', { streamId });
  try {
    // Log data access for compliance
    await logDataAccess(env, userId, 'live_stream', streamId, request);
    
    const stub = getStub(env, streamId);
    const res = await stub.fetch(`https://do/${streamId}/join?userId=${encodeURIComponent(userId)}`, { method: 'POST' });
    return res;
  } finally {
    await endSpan(env, span, 'live.join');
  }
}

