export async function sendStreamGift(request: Request, env: Env): Promise<Response> {
  const url = new URL(request.url);
  const streamId = url.pathname.split('/')[2];
  const body: any = await request.json().catch(() => ({}));
  const userId = body.userId;
  const giftType = body.giftType;
  if (!giftType) return jsonResponse(false, null, 'MISSING_GIFT_TYPE', 400);
  if (!userId) return jsonResponse(false, null, 'MISSING_USER', 400);
  
  // Region-aware age gating: gift sending requires 18+ (or region-specific)
  const ageCheck = await ensureMinimumAgeRegionAware(env, userId, { ip: request.headers.get('cf-connecting-ip') || undefined });
  // Allow gift sending if user meets required age; previous logic incorrectly blocked when requiredAge < 18
  if (!ageCheck.allowed) {
    await logRestrictedAccess(env, userId, 'live_stream_gift', ageCheck.region, ageCheck.requiredAge, request);
    return jsonResponse(false, null, 'AGE_RESTRICTED', 403);
  }
  
  // Basic mapping of gift types to economic value (placeholder values)
  const giftValueMap: Record<string, number> = { rose: 10, diamond: 100, rocket: 500, star: 50, gold: 250 };
  const giftValue = giftValueMap[giftType] || 10;
  // Run fraud detection (rate limiting + statistical anomaly + pattern checks)
  const fraudResult = await detectGiftFraud(env, userId, giftValue, {
    ipAddress: request.headers.get('cf-connecting-ip') || undefined,
    deviceId: request.headers.get('x-device-id') || undefined,
    recipientId: streamId // treating stream as recipient context for circular gifting detection
  });
  if (fraudResult.shouldBlock) {
    return jsonResponse(false, { reasons: fraudResult.reasons }, 'FRAUD_BLOCKED', 429);
  }
  if (fraudResult.reasons.includes('RATE_LIMIT_EXCEEDED')) {
    return jsonResponse(false, { reasons: fraudResult.reasons }, 'RATE_LIMIT_EXCEEDED', 429);
  }
  const span = startSpan('live.gift', { streamId, riskScore: fraudResult.riskScore });
  try {
    const stub = getStub(env, streamId);
    const res = await stub.fetch(`https://do/${streamId}/gift`, { method: 'POST', body: JSON.stringify({ giftType, value: giftValue, fraudRisk: fraudResult.riskScore }), headers: { 'Content-Type': 'application/json' } });
    return res;
  } finally {
    await endSpan(env, span, 'live.gift');
  }
}

