/**
 * Live Feed Handler - API endpoints for live stream feeds
 * 
 * Endpoints:
 * - GET /feed/live - Get live streams feed
 * - GET /feed/live/trending - Get trending live streams
 * - GET /feed/live/category/:category - Get live streams by category
 * - GET /feed/live/search - Search live streams
 * - POST /live/batch-stats - Get batch live stream statistics
 */

import { RouteHandler } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { verifyToken } from '../utils/jwt.utils';
import { ValidationUtils, ErrorHandler, SecurityUtils } from '../../../../services/shared';

/**
 * Get live streams feed
 */
export const getLiveFeed: RouteHandler = async (request, env, _ctx, _params) => {
  try {
    const url = new URL(request.url);
    const limit = parseInt(url.searchParams.get('limit') || '20');
    const cursor = url.searchParams.get('cursor');
    const followingOnly = url.searchParams.get('followingOnly') === 'true';
    const category = url.searchParams.get('category');
    
    // Get user ID if authenticated
    let userId: string | null = null;
    const authHeader = request.headers.get('Authorization');
    if (authHeader?.startsWith('Bearer ')) {
      const token = authHeader.substring(7);
      try {
        const payload = await verifyToken(token, env);
        if (payload) {
          userId = payload.userId;
        }
      } catch (e) {
        // Continue without auth
      }
    }
    
    // Build query based on filters
    let query = `
      SELECT 
        ls.id,
        ls.title,
        ls.creator_id as creatorId,
        u.username as creatorName,
        u.avatar_url as creatorAvatarUrl,
        ls.thumbnail_url as thumbnailUrl,
        ls.viewer_count as viewerCount,
        ls.is_live as isLive,
        ls.started_at as startedAt,
        ls.category,
        ls.metadata
      FROM live_streams ls
      JOIN users u ON ls.creator_id = u.id
      WHERE ls.is_live = 1
    `;
    
    const params: any[] = [];
    
    // Filter by following
    if (followingOnly && userId) {
      query += ` AND ls.creator_id IN (
        SELECT followed_id FROM followers WHERE follower_id = ?
      )`;
      params.push(userId);
    }
    
    // Filter by category
    if (category) {
      query += ` AND ls.category = ?`;
      params.push(category);
    }
    
    // Add cursor pagination
    if (cursor) {
      query += ` AND ls.started_at < ?`;
      params.push(cursor);
    }
    
    // Order by viewer count and recency
    query += ` ORDER BY ls.viewer_count DESC, ls.started_at DESC LIMIT ?`;
    params.push(limit + 1); // +1 to check if there are more
    
    const stmt = env.DB.prepare(query).bind(...params);
    const result = await stmt.all();
    
    const items = result.results || [];
    const hasMore = items.length > limit;
    const nextCursor = hasMore ? items[limit - 1].startedAt : null;
    
    // Trim to limit
    const feedItems = items.slice(0, limit);
    
    // Check if user is following creators
    if (userId) {
      const creatorIds = feedItems.map((item: any) => item.creatorId);
      const followingStmt = env.DB.prepare(`
        SELECT followed_id FROM followers WHERE follower_id = ? AND followed_id IN (${creatorIds.map(() => '?').join(',')})
      `).bind(userId, ...creatorIds);
      
      const followingResult = await followingStmt.all();
      const followingSet = new Set(followingResult.results?.map((r: any) => r.followed_id));
      
      feedItems.forEach((item: any) => {
        item.isFollowing = followingSet.has(item.creatorId);
      });
    }
    
    return jsonResponse(true, {
      items: feedItems,
      nextCursor,
      hasMore,
      totalCount: items.length,
      metadata: {
        followingOnly,
        category,
      },
    });
  } catch (error) {
    console.error('Get live feed error:', error);
    return jsonResponse(false, null, 'FEED_ERROR', 500);
  }
};

/**
 * Get trending live streams
 */
export const getTrendingLive: RouteHandler = async (request, env, _ctx, _params) => {
  try {
    const url = new URL(request.url);
    const limit = parseInt(url.searchParams.get('limit') || '20');
    
    // Get top live streams by engagement
    const query = `
      SELECT 
        ls.id,
        ls.title,
        ls.creator_id as creatorId,
        u.username as creatorName,
        u.avatar_url as creatorAvatarUrl,
        ls.thumbnail_url as thumbnailUrl,
        ls.viewer_count as viewerCount,
        ls.is_live as isLive,
        ls.started_at as startedAt,
        ls.category,
        ls.metadata,
        (ls.viewer_count * 1.0 + COALESCE(le.like_count, 0) * 2.0 + COALESCE(le.share_count, 0) * 3.0) as engagement_score
      FROM live_streams ls
      JOIN users u ON ls.creator_id = u.id
      LEFT JOIN (
        SELECT 
          stream_id,
          COUNT(CASE WHEN event_type = 'like' THEN 1 END) as like_count,
          COUNT(CASE WHEN event_type = 'share' THEN 1 END) as share_count
        FROM live_events
        WHERE created_at > datetime('now', '-1 hour')
        GROUP BY stream_id
      ) le ON ls.id = le.stream_id
      WHERE ls.is_live = 1
      ORDER BY engagement_score DESC, ls.viewer_count DESC
      LIMIT ?
    `;
    
    const stmt = env.DB.prepare(query).bind(limit);
    const result = await stmt.all();
    
    return jsonResponse(true, {
      items: result.results || [],
      metadata: {
        type: 'trending',
        calculatedAt: new Date().toISOString(),
      },
    });
  } catch (error) {
    console.error('Get trending live error:', error);
    return jsonResponse(false, null, 'TRENDING_ERROR', 500);
  }
};

/**
 * Get live streams by category
 */
export const getLiveByCategory: RouteHandler = async (request, env, _ctx, params) => {
  try {
    const category = params?.category;
    if (!category) {
      return jsonResponse(false, null, 'CATEGORY_REQUIRED', 400);
    }
    
    const url = new URL(request.url);
    const limit = parseInt(url.searchParams.get('limit') || '20');
    
    const query = `
      SELECT 
        ls.id,
        ls.title,
        ls.creator_id as creatorId,
        u.username as creatorName,
        u.avatar_url as creatorAvatarUrl,
        ls.thumbnail_url as thumbnailUrl,
        ls.viewer_count as viewerCount,
        ls.is_live as isLive,
        ls.started_at as startedAt,
        ls.category,
        ls.metadata
      FROM live_streams ls
      JOIN users u ON ls.creator_id = u.id
      WHERE ls.is_live = 1 AND ls.category = ?
      ORDER BY ls.viewer_count DESC, ls.started_at DESC
      LIMIT ?
    `;
    
    const stmt = env.DB.prepare(query).bind(category, limit);
    const result = await stmt.all();
    
    return jsonResponse(true, {
      items: result.results || [],
      category,
      totalCount: result.results?.length || 0,
    });
  } catch (error) {
    console.error('Get live by category error:', error);
    return jsonResponse(false, null, 'CATEGORY_ERROR', 500);
  }
};

/**
 * Search live streams
 */
export const searchLiveStreams: RouteHandler = async (request, env, _ctx, _params) => {
  try {
    const url = new URL(request.url);
    const query = url.searchParams.get('q');
    const limit = parseInt(url.searchParams.get('limit') || '20');
    
    if (!query) {
      return jsonResponse(false, null, 'QUERY_REQUIRED', 400);
    }
    
    const searchQuery = `
      SELECT 
        ls.id,
        ls.title,
        ls.creator_id as creatorId,
        u.username as creatorName,
        u.avatar_url as creatorAvatarUrl,
        ls.thumbnail_url as thumbnailUrl,
        ls.viewer_count as viewerCount,
        ls.is_live as isLive,
        ls.started_at as startedAt,
        ls.category,
        ls.metadata
      FROM live_streams ls
      JOIN users u ON ls.creator_id = u.id
      WHERE ls.is_live = 1 
        AND (
          ls.title LIKE ? 
          OR u.username LIKE ?
          OR ls.category LIKE ?
        )
      ORDER BY ls.viewer_count DESC
      LIMIT ?
    `;
    
    const searchTerm = `%${query}%`;
    const stmt = env.DB.prepare(searchQuery).bind(searchTerm, searchTerm, searchTerm, limit);
    const result = await stmt.all();
    
    return jsonResponse(true, {
      items: result.results || [],
      query,
      totalCount: result.results?.length || 0,
    });
  } catch (error) {
    console.error('Search live streams error:', error);
    return jsonResponse(false, null, 'SEARCH_ERROR', 500);
  }
};

/**
 * Get batch live stream statistics
 */
export const batchLiveStats: RouteHandler = async (request, env, _ctx, _params) => {
  try {
    const body = await request.json() as { streamIds: string[] };
    const { streamIds } = body;
    
    if (!streamIds || !Array.isArray(streamIds) || streamIds.length === 0) {
      return jsonResponse(false, null, 'STREAM_IDS_REQUIRED', 400);
    }
    
    const placeholders = streamIds.map(() => '?').join(',');
    const query = `
      SELECT 
        id,
        viewer_count as viewerCount,
        is_live as isLive,
        started_at as startedAt
      FROM live_streams
      WHERE id IN (${placeholders})
    `;
    
    const stmt = env.DB.prepare(query).bind(...streamIds);
    const result = await stmt.all();
    
    // Convert to map
    const stats: Record<string, any> = {};
    (result.results || []).forEach((row: any) => {
      stats[row.id] = {
        viewerCount: row.viewerCount,
        isLive: row.isLive === 1,
        startedAt: row.startedAt,
      };
    });
    
    return jsonResponse(true, { stats });
  } catch (error) {
    console.error('Batch live stats error:', error);
    return jsonResponse(false, null, 'BATCH_STATS_ERROR', 500);
  }
};
