/**
 * UNIFIED CHAT HANDLER - Uses Unified Pipeline
 * 
 * ✅ Consolidates:
 * - chat.handler.stable.ts (production chat)
 * - chat.handler.enhanced.ts (privacy chat)
 * - Single source of truth
 * - Uses UnifiedPipeline for all stages
 */

import type { Env, RouteHandler } from '../types';
import { UnifiedPipeline } from '../core/unified-pipeline';
import { requireAuth } from '../middleware';
import { ValidationUtils } from '../../../../services/shared';

// ============================================================================
// MAIN HANDLER - Uses Unified Pipeline
// ============================================================================

export const handleChatRequest: RouteHandler = async (request, env, ctx) => {
  const pipeline = new UnifiedPipeline(env, ctx, request);

  return pipeline.execute(async (pipelineCtx) => {
    // Extract from auth middleware
    const authResult = await requireAuth(request, env);
    if (authResult instanceof Response) return authResult;

    const userId = authResult.userId;
    pipelineCtx.metadata.set('userId', userId);

    const url = new URL(request.url);
    const path = url.pathname.replace(/^\/v1/, '');

    // Route to specific chat handler
    if (path.startsWith('/chat/conversations')) {
      return handleGetConversations(request, env, userId, pipelineCtx);
    }

    if (path.startsWith('/chat/messages')) {
      if (request.method === 'GET') {
        return handleGetMessages(request, env, userId, pipelineCtx);
      }
      if (request.method === 'POST') {
        return handleSendMessage(request, env, userId, ctx, pipelineCtx);
      }
    }

    if (path.startsWith('/chat/typing')) {
      return handleTypingIndicator(request, env, userId, pipelineCtx);
    }

    if (path.startsWith('/chat/presence')) {
      return handlePresence(request, env, userId, pipelineCtx);
    }

    if (path.startsWith('/chat/read')) {
      return handleMarkAsRead(request, env, userId, pipelineCtx);
    }

    return new Response(JSON.stringify({ error: 'Not found' }), { status: 404 });
  });
};

// ============================================================================
// CONVERSATION OPERATIONS
// ============================================================================

async function handleGetConversations(
  _request: Request,
  env: Env,
  userId: string,
  pipelineCtx: any
): Promise<Response> {
  try {
    // Query conversations
    const conversations = await env.DB.prepare(
      `SELECT 
        c.id, c.user1_id, c.user2_id, c.last_message_content,
        c.last_message_at, c.unread_count, c.created_at,
        u1.username as user1_username, u1.avatar_url as user1_avatar,
        u2.username as user2_username, u2.avatar_url as user2_avatar
      FROM conversations c
      JOIN users u1 ON c.user1_id = u1.id
      JOIN users u2 ON c.user2_id = u2.id
      WHERE c.user1_id = ? OR c.user2_id = ?
      ORDER BY c.last_message_at DESC
      LIMIT 50`
    ).bind(userId, userId).all();

    // Get presence for participants
    type ConversationRow = {
      id: string;
      user1_id: string;
      user2_id: string;
      last_message_content: string;
      last_message_at: string;
      unread_count: number;
      created_at: string;
      user1_username: string;
      user1_avatar: string;
      user2_username: string;
      user2_avatar: string;
    };

    const participantIds = new Set<string>();
    (conversations.results as ConversationRow[]).forEach((conv) => {
      participantIds.add(conv.user1_id);
      participantIds.add(conv.user2_id);
    });

    const presenceMap = new Map<string, { status: string; lastSeen: string }>();
    for (const id of participantIds) {
      const presenceData = await env.KV.get(`presence:${id}`);
      if (presenceData) {
        presenceMap.set(id, JSON.parse(presenceData));
      } else {
        presenceMap.set(id, {
          status: 'offline',
          lastSeen: new Date().toISOString(),
        });
      }
    }

    // Format response
    const result = (conversations.results as ConversationRow[]).map((conv) => {
      const otherUserId = conv.user1_id === userId ? conv.user2_id : conv.user1_id;
      const presence = presenceMap.get(otherUserId);

      return {
        id: conv.id,
        participant: {
          id: otherUserId,
          username: conv.user1_id === userId ? conv.user2_username : conv.user1_username,
          avatar: conv.user1_id === userId ? conv.user2_avatar : conv.user1_avatar,
          presence: presence || { status: 'offline', lastSeen: new Date().toISOString() },
        },
        lastMessage: {
          content: conv.last_message_content,
          timestamp: conv.last_message_at,
        },
        unreadCount: conv.unread_count,
        createdAt: conv.created_at,
      };
    });

    pipelineCtx.metadata.set('conversationCount', result.length);

    return new Response(JSON.stringify({ success: true, data: result }), {
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (error) {
    throw new Error(`Get conversations failed: ${(error as Error).message}`);
  }
}

async function handleGetMessages(
  request: Request,
  env: Env,
  userId: string,
  pipelineCtx: any
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const conversationId = url.searchParams.get('conversationId');

    if (!conversationId) {
      return new Response(JSON.stringify({ error: 'Missing conversationId' }), {
        status: 400,
      });
    }

    // Verify user is part of conversation
    const convCheck = await env.DB.prepare(
      'SELECT * FROM conversations WHERE id = ? AND (user1_id = ? OR user2_id = ?)'
    ).bind(conversationId, userId, userId).all();

    if (!convCheck.results.length) {
      return new Response(JSON.stringify({ error: 'Unauthorized' }), {
        status: 403,
      });
    }

    // Get messages
    const messages = await env.DB.prepare(
      `SELECT * FROM messages 
       WHERE conversation_id = ? 
       ORDER BY created_at DESC 
       LIMIT 100`
    ).bind(conversationId).all();

    pipelineCtx.metadata.set('messageCount', messages.results.length);

    return new Response(JSON.stringify({ success: true, data: messages.results }), {
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (error) {
    throw new Error(`Get messages failed: ${(error as Error).message}`);
  }
}

async function handleSendMessage(
  request: Request,
  env: Env,
  userId: string,
  ctx: ExecutionContext,
  pipelineCtx: any
): Promise<Response> {
  try {
    const body = (await request.json()) as {
      conversationId: string;
      content: string;
      type?: string;
      mediaUrl?: string;
    };

    const { conversationId, content, type = 'text', mediaUrl } = body;

    // Validate
    if (!conversationId || !content) {
      return new Response(
        JSON.stringify({ error: 'Missing required fields' }),
        { status: 400 }
      );
    }

    // Create message
    const messageId = crypto.randomUUID();
    const now = new Date().toISOString();

    // Store in D1
    await env.DB.prepare(
      `INSERT INTO messages (id, conversation_id, sender_id, content, type, media_url, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`
    ).bind(messageId, conversationId, userId, content, type, mediaUrl, now).run();

    // Update conversation
    await env.DB.prepare(
      `UPDATE conversations 
       SET last_message_content = ?, last_message_at = ?
       WHERE id = ?`
    ).bind(content, now, conversationId).run();

    // Broadcast via DO (async)
    if (env.CHAT_ROOM) {
      const roomId = env.CHAT_ROOM.idFromName(`conv-${conversationId}`);
      const stub = env.CHAT_ROOM.get(roomId);
      ctx.waitUntil(
        stub.fetch(new Request('https://internal/broadcast', {
          method: 'POST',
          body: JSON.stringify({
            type: 'message',
            conversationId,
            messageId,
            senderId: userId,
            content,
            messageType: type,
            timestamp: now,
          }),
        }))
      );
    }

    pipelineCtx.metadata.set('messageSent', true);
    pipelineCtx.metadata.set('messageId', messageId);

    return new Response(
      JSON.stringify({
        success: true,
        data: {
          id: messageId,
          status: 'sent',
          timestamp: now,
        },
      }),
      { headers: { 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    throw new Error(`Send message failed: ${(error as Error).message}`);
  }
}

// ============================================================================
// REAL-TIME OPERATIONS
// ============================================================================

async function handleTypingIndicator(
  request: Request,
  env: Env,
  userId: string,
  pipelineCtx: any
): Promise<Response> {
  try {
    const body = (await request.json()) as {
      conversationId: string;
      isTyping: boolean;
    };

    const { conversationId, isTyping } = body;

    // Store typing state in KV
    const key = `typing:${conversationId}:${userId}`;
    if (isTyping) {
      await env.KV.put(key, 'true', { expirationTtl: 5 });
    } else {
      await env.KV.delete(key);
    }

    pipelineCtx.metadata.set('typingUpdated', true);

    return new Response(JSON.stringify({ success: true }), {
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (error) {
    throw new Error(`Typing indicator failed: ${(error as Error).message}`);
  }
}

async function handlePresence(
  request: Request,
  env: Env,
  userId: string,
  pipelineCtx: any
): Promise<Response> {
  try {
    const body = (await request.json()) as { status: string };
    const { status } = body;

    // Store presence in KV (1 hour TTL)
    await env.KV.put(
      `presence:${userId}`,
      JSON.stringify({
        status,
        lastSeen: new Date().toISOString(),
      }),
      { expirationTtl: 3600 }
    );

    pipelineCtx.metadata.set('presenceUpdated', true);

    return new Response(JSON.stringify({ success: true }), {
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (error) {
    throw new Error(`Presence update failed: ${(error as Error).message}`);
  }
}

async function handleMarkAsRead(
  request: Request,
  env: Env,
  userId: string,
  pipelineCtx: any
): Promise<Response> {
  try {
    const body = (await request.json()) as {
      conversationId: string;
      messageId: string;
    };

    const { conversationId, messageId } = body;

    // Update message status
    await env.DB.prepare(
      'UPDATE messages SET status = ? WHERE id = ? AND conversation_id = ?'
    ).bind('read', messageId, conversationId).run();

    // Reset unread count
    await env.DB.prepare(
      'UPDATE conversations SET unread_count = 0 WHERE id = ? AND user2_id = ?'
    ).bind(conversationId, userId).run();

    pipelineCtx.metadata.set('markedAsRead', true);

    return new Response(JSON.stringify({ success: true }), {
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (error) {
    throw new Error(`Mark as read failed: ${(error as Error).message}`);
  }
}
