/**
 * Agora Token Service for Cloudflare Workers
 * Lightweight implementation using agora-token package
 */

import { RtcTokenBuilder, RtcRole } from 'agora-token';

export interface AgoraTokenParams {
  channelName: string;
  uid: number | string;
  role?: 'publisher' | 'subscriber';
  expirySeconds?: number;
}

export interface AgoraTokenResponse {
  token: string;
  uid: number | string;
  expiresAt: number;
  channelName: string;
}

export class AgoraService {
  private appId: string;
  private appCertificate: string;
  private defaultExpiry: number;
  private tokenCache: Map<string, { token: string; expiresAt: number }>;

  constructor(appId: string, appCertificate: string, defaultExpiry = 43200) {
    if (!appId || !appCertificate) {
      throw new Error('Agora credentials required: appId and appCertificate');
    }

    this.appId = appId;
    this.appCertificate = appCertificate;
    this.defaultExpiry = defaultExpiry; // 12 hours default
    this.tokenCache = new Map();
  }

  /**
   * Generate Agora RTC token
   */
  async generateToken(params: AgoraTokenParams): Promise<AgoraTokenResponse> {
    const {
      channelName,
      uid,
      role = 'publisher',
      expirySeconds = this.defaultExpiry,
    } = params;

    // Validate parameters
    if (!channelName) {
      throw new Error('channelName is required');
    }

    if (uid === undefined || uid === null) {
      throw new Error('uid is required');
    }

    // Validate role
    if (!['publisher', 'subscriber'].includes(role)) {
      throw new Error('role must be "publisher" or "subscriber"');
    }

    // Convert uid to number if string
    const numericUid = typeof uid === 'string' ? parseInt(uid, 10) : uid;
    
    if (isNaN(numericUid) || numericUid < 0 || numericUid > 2 ** 32 - 1) {
      throw new Error('uid must be a valid number between 0 and 4294967295');
    }

    // Check cache first
    const cacheKey = `${channelName}:${numericUid}:${role}`;
    const cached = this.tokenCache.get(cacheKey);
    
    if (cached && cached.expiresAt > Date.now() + 300000) {
      // Return cached token if it has more than 5 minutes left
      return {
        token: cached.token,
        uid: numericUid,
        expiresAt: cached.expiresAt,
        channelName,
      };
    }

    // Determine Agora role
    const agoraRole = role === 'subscriber' ? RtcRole.SUBSCRIBER : RtcRole.PUBLISHER;

    // Calculate expiry
    const currentTimeInSeconds = Math.floor(Date.now() / 1000);
    const privilegeExpiredTs = currentTimeInSeconds + expirySeconds;
    const expiresAtMs = privilegeExpiredTs * 1000;

    // Generate token
    const token = RtcTokenBuilder.buildTokenWithUid(
      this.appId,
      this.appCertificate,
      channelName,
      numericUid,
      agoraRole,
      privilegeExpiredTs
    );

    // Cache the token
    this.tokenCache.set(cacheKey, {
      token,
      expiresAt: expiresAtMs,
    });

    // Clean up expired cache entries periodically
    this.cleanupCache();

    return {
      token,
      uid: numericUid,
      expiresAt: expiresAtMs,
      channelName,
    };
  }

  /**
   * Renew an existing token
   */
  async renewToken(params: AgoraTokenParams): Promise<AgoraTokenResponse> {
    // For renewal, invalidate cache and generate new token
    const cacheKey = `${params.channelName}:${params.uid}:${params.role || 'publisher'}`;
    this.tokenCache.delete(cacheKey);

    return this.generateToken(params);
  }

  /**
   * Check if Agora is properly configured
   */
  isConfigured(): boolean {
    return !!(this.appId && this.appCertificate);
  }

  /**
   * Get health status
   */
  getHealth() {
    return {
      status: 'ok',
      configured: this.isConfigured(),
      cacheSize: this.tokenCache.size,
    };
  }

  /**
   * Clean up expired cache entries
   */
  private cleanupCache(): void {
    const now = Date.now();
    for (const [key, value] of this.tokenCache.entries()) {
      if (value.expiresAt <= now) {
        this.tokenCache.delete(key);
      }
    }

    // Limit cache size to prevent memory issues
    if (this.tokenCache.size > 1000) {
      const entries = Array.from(this.tokenCache.entries());
      entries.sort((a, b) => a[1].expiresAt - b[1].expiresAt);
      
      // Remove oldest 20% of entries
      const toRemove = Math.floor(entries.length * 0.2);
      for (let i = 0; i < toRemove; i++) {
        this.tokenCache.delete(entries[i][0]);
      }
    }
  }
}
