// Analytics Service for real-time metrics logging

import type { Env } from '../types';
import { ValidationUtils, ErrorHandler } from '../../../../services/shared';

export class AnalyticsService {
  constructor(private env: Env) {}
  
  /**
   * Log API request metrics
   */
  async logRequest(
    endpoint: string,
    method: string,
    statusCode: number,
    duration: number,
    userId?: string
  ): Promise<void> {
    if (!this.env.ANALYTICS) return;
    
    try {
      await this.env.ANALYTICS.writeDataPoint({
        blobs: [endpoint, method, statusCode.toString()],
        doubles: [duration],
        indexes: [userId || 'anonymous'],
      });
    } catch (error) {
      console.error('Analytics logging error:', error);
    }
  }
  
  /**
   * Log video view
   */
  async logVideoView(videoId: string, userId?: string): Promise<void> {
    if (!this.env.ANALYTICS) return;
    
    try {
      await this.env.ANALYTICS.writeDataPoint({
        blobs: ['video_view', videoId],
        doubles: [Date.now()],
        indexes: [userId || 'anonymous'],
      });
    } catch (error) {
      console.error('Analytics logging error:', error);
    }
  }
  
  /**
   * Log video upload
   */
  async logVideoUpload(
    videoId: string,
    userId: string,
    fileSize: number,
    duration: number
  ): Promise<void> {
    if (!this.env.ANALYTICS) return;
    
    try {
      await this.env.ANALYTICS.writeDataPoint({
        blobs: ['video_upload', videoId, userId],
        doubles: [fileSize, duration],
        indexes: [userId],
      });
    } catch (error) {
      console.error('Analytics logging error:', error);
    }
  }
  
  /**
   * Log user action (like, comment, follow)
   */
  async logUserAction(
    action: string,
    userId: string,
    targetId: string
  ): Promise<void> {
    if (!this.env.ANALYTICS) return;
    
    try {
      await this.env.ANALYTICS.writeDataPoint({
        blobs: [action, userId, targetId],
        doubles: [Date.now()],
        indexes: [userId],
      });
    } catch (error) {
      console.error('Analytics logging error:', error);
    }
  }
}
