import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { ValidationUtils, ErrorHandler, SecurityUtils } from '../../../../services/shared';

/**
 * Accepts client-side performance telemetry posted by Flutter (debug/profile)
 * Payload example:
 * {
 *   frameTimes: number[]; // in ms
 *   networkLatencies: number[]; // in ms
 *   errors: { exception: string; stack?: string; library?: string; context?: string; ts: number }[];
 *   deviceTs: string; // ISO timestamp
 * }
 *
 * We store the raw payload for later analysis in a simple D1 table.
 * This endpoint is intentionally light-weight and can be guarded with optional auth.
 */
export async function postPerfTelemetry(req: Request, env: Env): Promise<Response> {
  try {
    const body = await req.json() as any;

    // Basic validation
    if (!body || typeof body !== 'object') {
      return new Response(
        JSON.stringify({ success: false, error: { code: 'INVALID_PAYLOAD', message: 'Body must be JSON object' } }),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Create table if not exists
    await env.DB.prepare(`
      CREATE TABLE IF NOT EXISTS perf_telemetry (
        id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
        device_ts TEXT,
        frame_times TEXT, -- JSON array
        network_latencies TEXT, -- JSON array
        errors TEXT, -- JSON array
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
      )
    `).run();

    const deviceTs = typeof body.deviceTs === 'string' ? body.deviceTs : new Date().toISOString();
    const frameTimes = Array.isArray(body.frameTimes) ? JSON.stringify(body.frameTimes) : JSON.stringify([]);
    const networkLatencies = Array.isArray(body.networkLatencies) ? JSON.stringify(body.networkLatencies) : JSON.stringify([]);
    const errors = Array.isArray(body.errors) ? JSON.stringify(body.errors) : JSON.stringify([]);

    await env.DB.prepare(`
      INSERT INTO perf_telemetry (device_ts, frame_times, network_latencies, errors)
      VALUES (?1, ?2, ?3, ?4)
    `).bind(deviceTs, frameTimes, networkLatencies, errors).run();

    return jsonResponse(true, { received: true });
  } catch (error) {
    console.error('[PerfTelemetry] Error:', error);
    return new Response(
      JSON.stringify({ success: false, error: { code: 'INTERNAL_ERROR', message: 'Failed to store telemetry' } }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
}
