import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { startSpan, endSpan } from '../utils/otel';
import { AgoraService } from '../services/agora.service';

let cachedService: AgoraService | null = null;

function getAgoraService(env: Env): AgoraService {
  if (cachedService) return cachedService;

  if (!env.AGORA_APP_ID || !env.AGORA_APP_CERTIFICATE) {
    throw new Error('Agora not configured');
  }

  cachedService = new AgoraService(
    env.AGORA_APP_ID,
    env.AGORA_APP_CERTIFICATE
  );

  return cachedService;
}

async function parseJson(request: Request) {
  try {
    return await request.json();
  } catch (error) {
    return null;
  }
}

export async function generateToken(
  request: Request,
  env: Env
): Promise<Response> {
  const span = startSpan('agora.generateToken');

  try {
    if (!env.AGORA_APP_ID || !env.AGORA_APP_CERTIFICATE) {
      return jsonResponse(false, null, 'AGORA_NOT_CONFIGURED', 503);
    }

    const body = await parseJson(request);
    if (!body) {
      return jsonResponse(false, null, 'INVALID_BODY', 400);
    }

    const channelName = body.channelName as string | undefined;
    const uidRaw = body.uid as number | string | undefined;
    const role = (body.role as string | undefined) || 'publisher';

    const uid = uidRaw === undefined ? undefined : Number(uidRaw);

    try {
      const service = getAgoraService(env);
      const result = await service.generateToken({
        channelName,
        uid,
        role,
      });

      return jsonResponse(true, result, null, 200);
    } catch (error: any) {
      const message = error?.message || 'Failed to generate token';
      const isRateLimit = message.toLowerCase().includes('rate limit');
      const code = isRateLimit ? 429 : 400;
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'AGORA_TOKEN_ERROR',
            message,
          },
        }),
        {
          status: code,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
  } finally {
    await endSpan(env, span, 'agora.generateToken');
  }
}

