export async function health(_request: Request, env: Env): Promise<Response> {
  try {
    if (!env.AGORA_APP_ID || !env.AGORA_APP_CERTIFICATE) {
      return jsonResponse(false, null, 'AGORA_NOT_CONFIGURED', 503);
    }

    const service = getAgoraService(env);
    return jsonResponse(true, service.getHealth());
  } catch (error: any) {
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'AGORA_HEALTH_ERROR',
          message: error?.message || 'Failed to get Agora health',
        },
      }),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
}