// REGION_AGE_POLICY: Dynamic, region-aware age policy engine for global compliance
// Supports GDPR, DSA, COPPA, and custom rules per region
// Loads policy from ENV/KV, with fallback to DEFAULT_REGION_AGE_POLICY

import type { Env } from '../types';

export interface RegionAgePolicy {
  [region: string]: {
    minimumAge: number;
    residencyRequired?: boolean;
    policyName?: string; // e.g. 'GDPR', 'COPPA', 'DSA', 'Custom'
    notes?: string;
  };
}

export const DEFAULT_REGION_AGE_POLICY: RegionAgePolicy = {
  'US': { minimumAge: 13, policyName: 'COPPA', notes: 'Children Online Privacy Protection Act' },
  'EU': { minimumAge: 16, residencyRequired: true, policyName: 'GDPR', notes: 'General Data Protection Regulation' },
  'UK': { minimumAge: 13, residencyRequired: true, policyName: 'DSA', notes: 'Digital Services Act' },
  'CA': { minimumAge: 13, policyName: 'PIPEDA' },
  'BR': { minimumAge: 12, policyName: 'LGPD' },
  'IN': { minimumAge: 18, policyName: 'IT Rules' },
  'RU': { minimumAge: 14, policyName: 'FZ-152' },
  'CN': { minimumAge: 14, policyName: 'PIPL' },
  'KR': { minimumAge: 14, policyName: 'PIPA' },
  'JP': { minimumAge: 13, policyName: 'APPI' },
  'GLOBAL': { minimumAge: 13, policyName: 'Default' },
};

// Loads region age policy from ENV.KV or falls back to default
export async function loadRegionAgePolicy(env: Env): Promise<RegionAgePolicy> {
  try {
    if (env.CONFIG) {
      const raw = await env.CONFIG.get('REGION_AGE_POLICY', 'json');
      if (raw && typeof raw === 'object') return raw as RegionAgePolicy;
    }
  } catch {}
  return DEFAULT_REGION_AGE_POLICY;
}

// Resolves region from IP, device locale, or user profile
export function resolveUserRegion({ ip: _ip, locale, profileRegion }: { ip?: string; locale?: string; profileRegion?: string }): string {
  // Priority: profileRegion > locale > ip (geoip lookup)
  if (profileRegion) return profileRegion;
  if (locale && locale.length >= 2) return locale.slice(-2).toUpperCase();
  // Fallback: use 'GLOBAL' if region cannot be determined
  return 'GLOBAL';
}

// Returns minimum age for region, or global default
export function getMinimumAgeForRegion(policy: RegionAgePolicy, region: string): number {
  return policy[region]?.minimumAge ?? policy['GLOBAL'].minimumAge;
}

// Returns residency enforcement for region
export function isResidencyRequired(policy: RegionAgePolicy, region: string): boolean {
  return !!policy[region]?.residencyRequired;
}
