// Authentication middleware with Firebase + JWT support

import type { Env, RouteHandler } from '../types';
import { verifyToken } from '../utils/jwt.utils';
import { verifyFirebaseToken, getOrCreateUserFromFirebase, extractFirebaseToken } from '../utils/firebase-admin';

/**
 * Authentication middleware that supports both Firebase ID tokens and Workers JWT
 * Automatically creates users on first Firebase login
 */
export function requireAuth(handler: RouteHandler): RouteHandler {
  return async (request, env, ctx, params) => {
    const authHeader = request.headers.get('Authorization');
    
    if (!authHeader) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'UNAUTHORIZED',
            message: 'Missing authorization header',
          },
        }),
        {
          status: 401,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    // Centralized Bearer parsing: only accept "Bearer <token>"
    const token = extractFirebaseToken(authHeader);
    if (!token) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'UNAUTHORIZED',
            message: 'Invalid authorization header format',
          },
        }),
        {
          status: 401,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    // Try Firebase token first (most common for mobile apps)
    try {
      const firebaseUser = await verifyFirebaseToken(token, env);
      if (firebaseUser) {
        // Get or create user in D1
        const user = await getOrCreateUserFromFirebase(env, firebaseUser);
        if (user) {
          // Attach user ID to request for handlers
          (request as any).userId = user.id;
          (request as any).user = user;
          return handler(request, env, ctx, params);
        }
      }
    } catch (firebaseError) {
      // Minimal telemetry without secrets
      console.log('Firebase verification failed; will attempt JWT fallback');
    }
    
    // Fallback to Workers JWT (for legacy or direct API access)
    try {
      const payload = await verifyToken(token, env);
      if (payload) {
        // Attach user ID to request for handlers
        (request as any).userId = payload.userId;
        return handler(request, env, ctx, params);
      }
    } catch (jwtError) {
      console.log('JWT verification failed');
    }
    
    // Both authentication methods failed
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'UNAUTHORIZED',
          message: 'Invalid or expired token',
        },
      }),
      {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  };
}

/**
 * Optional authentication middleware
 * Attaches user if token is valid, but doesn't block request if missing
 */
export function optionalAuth(handler: RouteHandler): RouteHandler {
  return async (request, env, ctx, params) => {
    const authHeader = request.headers.get('Authorization');
    
    if (authHeader) {
      const token = extractFirebaseToken(authHeader);
      if (token) {
        // Try Firebase token
        try {
          const firebaseUser = await verifyFirebaseToken(token, env);
          if (firebaseUser) {
            const user = await getOrCreateUserFromFirebase(env, firebaseUser);
            if (user) {
              (request as any).userId = user.id;
              (request as any).user = user;
            }
          }
        } catch {
          // Try Workers JWT
          try {
            const payload = await verifyToken(token, env);
            if (payload) {
              (request as any).userId = payload.userId;
            }
          } catch {
            // Ignore auth errors for optional auth
          }
        }
      }
    }
    
    return handler(request, env, ctx, params);
  };
}

/**
 * Rate limiting middleware for sensitive endpoints
 */
export function rateLimit(
  maxAttempts: number,
  windowSeconds: number
): (handler: RouteHandler) => RouteHandler {
  return (handler: RouteHandler) => {
    return async (request, env, ctx, params) => {
      const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
      const key = `ratelimit:${ip}:${request.url}`;
      
      const currentStr = await env.RATE_LIMIT.get(key);
      const current = currentStr ? parseInt(currentStr) : 0;
      
      if (current >= maxAttempts) {
        return new Response(
          JSON.stringify({
            success: false,
            error: {
              code: 'RATE_LIMIT_EXCEEDED',
              message: `Too many requests. Try again in ${windowSeconds} seconds.`,
            },
          }),
          {
            status: 429,
            headers: { 'Content-Type': 'application/json' },
          }
        );
      }
      
      // Increment counter
      await env.RATE_LIMIT.put(key, (current + 1).toString(), {
        expirationTtl: windowSeconds,
      });
      
      return handler(request, env, ctx, params);
    };
  };
}
