import { Env } from '../types';

export type TelemetryEvent = {
  worker_id: string;
  execution_id: string;
  event: 'START' | 'SUCCESS' | 'FAILURE';
  timestamp: string;
  duration_ms: number | null;
  error_code: string | null;
  error_message: string | null;
  environment: 'dev' | 'staging' | 'prod';
};

export async function emitRuntimeTelemetry(env: Env, payload: TelemetryEvent, ctx?: ExecutionContext): Promise<void> {
  const url = env.AI_RUNTIME_INGEST_URL;
  if (!url) return; // telemetry disabled if not configured
  const body: TelemetryEvent = {
    ...payload,
    timestamp: payload.timestamp || new Date().toISOString(),
    environment: (env.AI_RUNTIME_ENVIRONMENT as any) || (env.ENVIRONMENT as any) || 'dev',
  } as TelemetryEvent;

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (env.AI_RUNTIME_TOKEN) headers['Authorization'] = `Bearer ${env.AI_RUNTIME_TOKEN}`;

  const task = fetch(url, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
  }).catch(() => undefined);

  if (ctx) {
    ctx.waitUntil(task);
  } else {
    await task;
  }
}
