import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { startSpan, endSpan } from '../utils/otel';
import { ensureMinimumAgeRegionAware } from '../utils/guard';
import { logDataAccess } from '../utils/legal_telemetry';
import { ValidationUtils, ErrorHandler, SecurityUtils } from '../../../../services/shared';

// Create subscription plan (admin)
export async function createPlan(request: Request, env: Env): Promise<Response> {
  const span = startSpan('subscription.createPlan');
  try {
    const body = await request.json().catch(()=>({})) as any;
    const { code, name, priceCents, interval, features } = body;
    if (!code || !name || !priceCents || !interval || !Array.isArray(features)) {
      return jsonResponse(false, null, 'INVALID_PLAN_DATA', 400);
    }
    await env.DB.prepare('INSERT INTO subscription_plans (code, name, price_cents, interval, features) VALUES (?1, ?2, ?3, ?4, ?5)')
      .bind(code, name, priceCents, interval, JSON.stringify(features)).run();
    return jsonResponse(true, { code });
  } catch (e:any) {
    return jsonResponse(false, null, 'PLAN_CREATE_FAILED', 500);
  } finally { await endSpan(env, span, 'subscription.createPlan'); }
}

export async function listPlans(_req: Request, env: Env): Promise<Response> {
  const span = startSpan('subscription.listPlans');
  try {
    const rs = await env.DB.prepare('SELECT code, name, price_cents, interval, features, active FROM subscription_plans WHERE active=1').all();
    const raw = rs.results || [];
    const plans = raw.map((p: any) => ({ ...p, features: JSON.parse(String(p.features || '[]')) }));
    return jsonResponse(true, { plans });
  } catch (e:any) {
    return jsonResponse(false, null, 'PLAN_LIST_FAILED', 500);
  } finally { await endSpan(env, span, 'subscription.listPlans'); }
}

export async function subscribe(request: Request, env: Env): Promise<Response> {
  const span = startSpan('subscription.subscribe');
  try {
    const body = await request.json().catch(()=>({})) as any;
    const { userId, planCode } = body;
    if (!userId || !planCode) return jsonResponse(false, null, 'INVALID_SUBSCRIBE', 400);
    
    // Region-aware age gating: paid subscriptions require 18+ minimum (may vary by jurisdiction)
    const ageCheck = await ensureMinimumAgeRegionAware(env, userId, { ip: request.headers.get('cf-connecting-ip') || undefined });
    if (!ageCheck.allowed || ageCheck.requiredAge < 18) {
      return jsonResponse(false, null, 'AGE_RESTRICTED', 403);
    }
    
    // Log subscription access for compliance
    await logDataAccess(env, userId, 'subscription', planCode, request);
    
    const plan = await env.DB.prepare('SELECT code, interval FROM subscription_plans WHERE code=?1 AND active=1').bind(planCode).first();
    if (!plan) return jsonResponse(false, null, 'PLAN_NOT_FOUND', 404);
    const expires = computeExpiry(String(plan.interval || 'monthly'));
    await env.DB.prepare('INSERT INTO user_subscriptions (user_id, plan_code, expires_at) VALUES (?1, ?2, ?3)')
      .bind(userId, planCode, expires).run();
    return jsonResponse(true, { userId, planCode, expiresAt: expires });
  } catch (e:any) {
    return jsonResponse(false, null, 'SUBSCRIBE_FAILED', 500);
  } finally { await endSpan(env, span, 'subscription.subscribe'); }
}

export async function mySubscription(request: Request, env: Env): Promise<Response> {
  const span = startSpan('subscription.mySubscription');
  try {
    const url = new URL(request.url); const userId = url.searchParams.get('userId');
    if (!userId) return jsonResponse(false, null, 'MISSING_USER', 400);
    const sub = await env.DB.prepare('SELECT plan_code, status, expires_at FROM user_subscriptions WHERE user_id=?1 AND status="active" ORDER BY started_at DESC LIMIT 1').bind(userId).first();
    if (!sub) return jsonResponse(true, { active: false });
    return jsonResponse(true, { active: true, planCode: sub.plan_code, expiresAt: sub.expires_at });
  } catch (e:any) {
    return jsonResponse(false, null, 'SUB_LOOKUP_FAILED', 500);
  } finally { await endSpan(env, span, 'subscription.mySubscription'); }
}

export async function cancelSubscription(request: Request, env: Env): Promise<Response> {
  const span = startSpan('subscription.cancel');
  try {
    const body = await request.json().catch(()=>({})) as any;
    const { userId } = body;
    if (!userId) return jsonResponse(false, null, 'MISSING_USER', 400);
    await env.DB.prepare('UPDATE user_subscriptions SET status="canceled", canceled_at=?2 WHERE user_id=?1 AND status="active"')
      .bind(userId, Date.now()).run();
    return jsonResponse(true, { canceled: true });
  } catch (e:any) {
    return jsonResponse(false, null, 'SUB_CANCEL_FAILED', 500);
  } finally { await endSpan(env, span, 'subscription.cancel'); }
}

export async function checkFeatureGate(request: Request, env: Env): Promise<Response> {
  const span = startSpan('subscription.featureGate');
  try {
    const url = new URL(request.url);
    const userId = url.searchParams.get('userId');
    const feature = url.searchParams.get('feature');
    if (!userId || !feature) return jsonResponse(false, null, 'MISSING_PARAMS', 400);
    const sub = await env.DB.prepare('SELECT plan_code FROM user_subscriptions WHERE user_id=?1 AND status="active" ORDER BY started_at DESC LIMIT 1').bind(userId).first();
    if (!sub) return jsonResponse(true, { allowed: false, reason: 'NO_SUBSCRIPTION' });
    const plan = await env.DB.prepare('SELECT features FROM subscription_plans WHERE code=?1').bind(sub.plan_code).first();
    if (!plan) return jsonResponse(true, { allowed: false, reason: 'PLAN_NOT_FOUND' });
    const features = JSON.parse(String((plan as any).features || '[]'));
    const allowed = features.includes(feature);
    if (allowed) {
      await env.DB.prepare('INSERT INTO feature_usage (user_id, feature_code) VALUES (?1, ?2)').bind(userId, feature).run();
    }
    return jsonResponse(true, { allowed });
  } catch (e:any) {
    return jsonResponse(false, null, 'FEATURE_CHECK_FAILED', 500);
  } finally { await endSpan(env, span, 'subscription.featureGate'); }
}

function computeExpiry(interval: string): string {
  const now = Date.now();
  const ms = interval === 'annual' ? 365*24*3600*1000 : 30*24*3600*1000;
  return new Date(now + ms).toISOString();
}
