/**
 * Test endpoint for Agora - NO AUTH (for staging testing only)
 * Remove this before production deployment!
 */

import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { AgoraService } from '../services/agora.service';

export async function testAgoraToken(
  request: Request,
  env: Env
): Promise<Response> {
  try {
    if (!env.AGORA_APP_ID || !env.AGORA_APP_CERTIFICATE) {
      return jsonResponse(false, null, 'AGORA_NOT_CONFIGURED', 503);
    }

    const body = await request.json().catch(() => null);
    if (!body) {
      return jsonResponse(false, null, 'INVALID_BODY', 400);
    }

    const { channelName, uid, role = 'publisher' } = body;

    if (!channelName || !uid) {
      return jsonResponse(false, null, 'Missing channelName or uid', 400);
    }

    const service = new AgoraService(
      env.AGORA_APP_ID,
      env.AGORA_APP_CERTIFICATE
    );

    const result = await service.generateToken({
      channelName,
      uid,
      role,
    });

    return jsonResponse(true, result, null, 200);
  } catch (error: any) {
    return jsonResponse(false, null, error?.message || 'Test failed', 500);
  }
}
