// Fraud Detection System - Z-Score Anomaly Detection for Gift & Payment Fraud
// Implements statistical anomaly detection, rate limiting, and pattern recognition

import type { Env } from '../types';

// Ensure required fraud tables exist (idempotent)
async function ensureFraudTables(env: Env) {
  try {
    await env.DB.prepare('CREATE TABLE IF NOT EXISTS gift_anomalies (userId TEXT, giftType TEXT, giftValue INTEGER, zScore REAL, mean REAL, stdDev REAL, timestamp INTEGER, ipAddress TEXT, deviceId TEXT)').run();
  } catch (e) {
    // swallow
  }
}

export interface FraudCheckResult {
  suspicious: boolean;
  riskScore: number; // 0-100
  reasons: string[];
  shouldBlock: boolean;
}

export interface GiftAnomaly {
  userId: string;
  giftType: string;
  value: number;
  zScore: number;
  timestamp: number;
  ipAddress?: string;
  deviceId?: string;
}

/**
 * Detect gift fraud using z-score anomaly detection
 * Flags gifts that are statistical outliers compared to user history
 */
export async function detectGiftFraud(
  env: Env,
  userId: string,
  giftValue: number,
  context: {
    ipAddress?: string;
    deviceId?: string;
    recipientId?: string;
  }
): Promise<FraudCheckResult> {
  const reasons: string[] = [];
  let riskScore = 0;
  
  try {
    // Ensure tables before queries (safe, lightweight)
    await ensureFraudTables(env);
    // 1. Check rate limiting (30 gifts per minute per user)
    const recentGifts = await env.DB.prepare(
      'SELECT COUNT(*) as count FROM gift_events WHERE userId = ? AND ts > ?'
    ).bind(userId, Date.now() - 60000).first();
    
    const giftCount = (recentGifts?.count as number) || 0;
    if (giftCount >= 30) {
      reasons.push('RATE_LIMIT_EXCEEDED');
      riskScore += 40;
    }
    
    // 2. Calculate z-score for gift value
    const stats = await env.DB.prepare(
      `SELECT AVG(value) as mean, COUNT(*) as count FROM gift_events 
       WHERE userId = ? AND ts > ?`
    ).bind(userId, Date.now() - 86400000 * 30).first(); // 30 days
    
    if (stats && (stats.count as number) > 5) {
      const mean = (stats.mean as number) || 0;
      
      // Calculate standard deviation
      const varQuery = await env.DB.prepare(
        `SELECT AVG((value - ?)*(value - ?)) as variance FROM gift_events 
         WHERE userId = ? AND ts > ?`
      ).bind(mean, mean, userId, Date.now() - 86400000 * 30).first();
      
      const variance = (varQuery?.variance as number) || 0;
      const stdDev = Math.sqrt(variance);
      
      // Calculate z-score
      const zScore = stdDev > 0 ? Math.abs((giftValue - mean) / stdDev) : 0;
      
      if (zScore > 3) {
        reasons.push('STATISTICAL_ANOMALY');
        riskScore += 30;
        
        // Log anomaly for review
        await env.DB.prepare(
          `INSERT INTO gift_anomalies (userId, giftValue, zScore, mean, stdDev, timestamp, ipAddress, deviceId)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
        ).bind(
          userId,
          giftValue,
          zScore,
          mean,
          stdDev,
          Date.now(),
          context.ipAddress || 'unknown',
          context.deviceId || 'unknown'
        ).run();
      }
    }
    
    // 3. Check IP-based fraud patterns
    if (context.ipAddress) {
      const ipGifts = await env.DB.prepare(
        'SELECT COUNT(DISTINCT userId) as userCount FROM gift_events WHERE ipAddress = ? AND ts > ?'
      ).bind(context.ipAddress, Date.now() - 3600000).first(); // 1 hour
      
      const userCount = (ipGifts?.userCount as number) || 0;
      if (userCount > 10) {
        reasons.push('IP_MULTIPLE_ACCOUNTS');
        riskScore += 25;
      }
    }
    
    // 4. Check device-based fraud patterns
    if (context.deviceId) {
      const deviceGifts = await env.DB.prepare(
        'SELECT COUNT(DISTINCT userId) as userCount FROM gift_events WHERE deviceId = ? AND ts > ?'
      ).bind(context.deviceId, Date.now() - 3600000).first();
      
      const userCount = (deviceGifts?.userCount as number) || 0;
      if (userCount > 5) {
        reasons.push('DEVICE_MULTIPLE_ACCOUNTS');
        riskScore += 25;
      }
    }
    
    // 5. Check for circular gifting (A→B→A pattern)
    if (context.recipientId) {
      const circularGift = await env.DB.prepare(
        `SELECT COUNT(*) as count FROM gift_events 
         WHERE userId = ? AND receiverId = ? AND ts > ?`
      ).bind(context.recipientId, userId, Date.now() - 86400000).first();
      
      const circularCount = (circularGift?.count as number) || 0;
      if (circularCount > 0) {
        reasons.push('CIRCULAR_GIFTING');
        riskScore += 20;
      }
    }
    
    // 6. Check for new account fraud
    const userAge = await env.DB.prepare(
      'SELECT created_at FROM users WHERE id = ?'
    ).bind(userId).first();
    
    if (userAge && userAge.created_at) {
      const accountAge = Date.now() - new Date(userAge.created_at as string).getTime();
      const daysSinceCreation = accountAge / (86400000);
      
      if (daysSinceCreation < 1 && giftValue > 500) {
        reasons.push('NEW_ACCOUNT_HIGH_VALUE');
        riskScore += 30;
      }
    }
    
    return {
      suspicious: reasons.length > 0,
      riskScore: Math.min(riskScore, 100),
      reasons,
      shouldBlock: riskScore >= 70, // Block at 70+ risk score
    };
  } catch (error) {
    console.error('Fraud detection error:', error);
    return {
      suspicious: false,
      riskScore: 0,
      reasons: ['DETECTION_ERROR'],
      shouldBlock: false,
    };
  }
}

/**
 * Detect payment fraud for withdrawals/payouts
 */
export async function detectPaymentFraud(
  env: Env,
  userId: string,
  amountCents: number,
  context: {
    ipAddress?: string;
    deviceId?: string;
    paymentMethod?: string;
  }
): Promise<FraudCheckResult> {
  const reasons: string[] = [];
  let riskScore = 0;
  
  try {
    // 1. Check for rapid succession payouts
    const recentPayouts = await env.DB.prepare(
      'SELECT COUNT(*) as count FROM payment_events WHERE user_id = ? AND event_type = ? AND created_at > ?'
    ).bind(userId, 'payout_pending', Date.now() - 3600000).first();
    
    const payoutCount = (recentPayouts?.count as number) || 0;
    if (payoutCount >= 5) {
      reasons.push('RAPID_PAYOUT_ATTEMPTS');
      riskScore += 35;
    }
    
    // 2. Check for unusually large payout
    const avgPayout = await env.DB.prepare(
      `SELECT AVG(amount_cents) as mean FROM payment_events 
       WHERE user_id = ? AND event_type LIKE 'payout%' AND created_at > ?`
    ).bind(userId, Date.now() - 86400000 * 30).first();
    
    const mean = (avgPayout?.mean as number) || 0;
    if (mean > 0 && amountCents > mean * 5) {
      reasons.push('UNUSUALLY_LARGE_PAYOUT');
      riskScore += 30;
    }
    
    // 3. Check IP reputation
    if (context.ipAddress) {
      const ipPayouts = await env.DB.prepare(
        'SELECT COUNT(DISTINCT user_id) as userCount FROM payment_events WHERE metadata LIKE ? AND created_at > ?'
      ).bind(`%${context.ipAddress}%`, Date.now() - 86400000).first();
      
      const userCount = (ipPayouts?.userCount as number) || 0;
      if (userCount > 20) {
        reasons.push('HIGH_RISK_IP');
        riskScore += 25;
      }
    }
    
    // 4. Check for pattern of failed payouts
    const failedPayouts = await env.DB.prepare(
      'SELECT COUNT(*) as count FROM payment_events WHERE user_id = ? AND status = ? AND created_at > ?'
    ).bind(userId, 'failed', Date.now() - 86400000 * 7).first();
    
    const failedCount = (failedPayouts?.count as number) || 0;
    if (failedCount >= 3) {
      reasons.push('MULTIPLE_FAILED_ATTEMPTS');
      riskScore += 20;
    }
    
    return {
      suspicious: reasons.length > 0,
      riskScore: Math.min(riskScore, 100),
      reasons,
      shouldBlock: riskScore >= 75,
    };
  } catch (error) {
    console.error('Payment fraud detection error:', error);
    return {
      suspicious: false,
      riskScore: 0,
      reasons: ['DETECTION_ERROR'],
      shouldBlock: false,
    };
  }
}

/**
 * Check rate limit for any action
 */
export async function checkRateLimit(
  env: Env,
  key: string,
  maxActions: number,
  windowMs: number
): Promise<{ allowed: boolean; remaining: number; resetAt: number }> {
  const cacheKey = `ratelimit:${key}`;
  const now = Date.now();
  
  try {
    const cached = await env.CACHE.get(cacheKey);
    
    if (cached) {
      const data = JSON.parse(cached);
      if (data.resetAt > now) {
        if (data.count >= maxActions) {
          return {
            allowed: false,
            remaining: 0,
            resetAt: data.resetAt,
          };
        }
        
        data.count++;
        await env.CACHE.put(cacheKey, JSON.stringify(data), {
          expirationTtl: Math.ceil((data.resetAt - now) / 1000),
        });
        
        return {
          allowed: true,
          remaining: maxActions - data.count,
          resetAt: data.resetAt,
        };
      }
    }
    
    // New window
    const resetAt = now + windowMs;
    await env.CACHE.put(
      cacheKey,
      JSON.stringify({ count: 1, resetAt }),
      { expirationTtl: Math.ceil(windowMs / 1000) }
    );
    
    return {
      allowed: true,
      remaining: maxActions - 1,
      resetAt,
    };
  } catch (error) {
    console.error('Rate limit check error:', error);
    // Fail open in case of errors
    return {
      allowed: true,
      remaining: maxActions,
      resetAt: now + windowMs,
    };
  }
}
