// Authentication handlers

import type { RouteHandler } from '../types';
import { ApiResponse } from '../types';
import { DatabaseService } from '../services/db.service';
import { hashPassword, verifyPassword } from '../utils/hash.utils';
import { generateToken, verifyToken } from '../utils/jwt.utils';
import { ValidationUtils, ErrorHandler, SecurityUtils } from '../../../../services/shared';

// Auth DTOs
interface RegisterBody { username: string; email: string; password: string; displayName: string }
interface LoginBody { email: string; password: string }
interface RefreshBody { refreshToken?: string }
interface LogoutBody { /* reserved for future: deviceId, sessionId */ }

export const register: RouteHandler = async (request, env, _ctx, _params) => {
  try {
    const body = await request.json().catch(() => ({})) as Partial<RegisterBody>;
    
    // Validate input
    if (!body.username || !body.email || !body.password || !body.displayName) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'VALIDATION_ERROR',
            message: 'Missing required fields',
          },
        } as ApiResponse),
        {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    const db = new DatabaseService(env);
    
    // Check if user already exists
    const existingUser = await db.getUserByEmail(body.email);
    if (existingUser) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'USER_EXISTS',
            message: 'User with this email already exists',
          },
        } as ApiResponse),
        {
          status: 409,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    // Hash password
    const passwordHash = await hashPassword(body.password);
    
    // Create user
    const user = await db.createUser({
      username: body.username,
      email: body.email,
      passwordHash,
      displayName: body.displayName,
      followersCount: 0,
      followingCount: 0,
      likesCount: 0,
      isVerified: false,
      isPremium: false,
    });
    
    // Generate tokens
    const accessToken = await generateToken(user.id, 'access', env);
    const refreshToken = await generateToken(user.id, 'refresh', env);
    
    // Remove password hash from response
    const { passwordHash: _, ...userWithoutPassword } = user;
    
    return new Response(
      JSON.stringify({
        success: true,
        data: {
          user: userWithoutPassword,
          tokens: {
            accessToken,
            refreshToken,
          },
        },
      } as ApiResponse),
      {
        status: 201,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Register error:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'Failed to register user',
        },
      } as ApiResponse),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
};

export const login: RouteHandler = async (request, env, _ctx, _params) => {
  try {
    const body = await request.json().catch(() => ({})) as Partial<LoginBody>;
    
    if (!body.email || !body.password) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'VALIDATION_ERROR',
            message: 'Email and password are required',
          },
        } as ApiResponse),
        {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    const db = new DatabaseService(env);
    const user = await db.getUserByEmail(body.email);
    
    if (!user) {
      // Record failed attempt (user not found still counts to prevent enumeration)
      const failKey = `authfail:${body.email.toLowerCase()}`;
      const failuresRaw = await env.RATE_LIMIT.get(failKey);
      const failures = failuresRaw ? Number.parseInt(failuresRaw, 10) : 0;
      const newFailures = failures + 1;
      await env.RATE_LIMIT.put(failKey, newFailures.toString(), { expirationTtl: 1800 }); // 30 min window
      if (newFailures >= 10) {
        await env.RATE_LIMIT.put(`lock:${body.email.toLowerCase()}`, '1', { expirationTtl: 1800 });
      }
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'INVALID_CREDENTIALS',
            message: 'Invalid email or password',
          },
        } as ApiResponse),
        {
          status: 401,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    // Check lock status
    const lock = await env.RATE_LIMIT.get(`lock:${body.email.toLowerCase()}`);
    if (lock) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'ACCOUNT_LOCKED',
            message: 'Too many failed attempts. Try again later.',
          },
        } as ApiResponse),
        { status: 423, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Verify password
    const valid = await verifyPassword(body.password, user.passwordHash);
    if (!valid) {
      // Increment failure counter
      const failKey = `authfail:${body.email.toLowerCase()}`;
      const failuresRaw = await env.RATE_LIMIT.get(failKey);
      const failures = failuresRaw ? Number.parseInt(failuresRaw, 10) : 0;
      const newFailures = failures + 1;
      await env.RATE_LIMIT.put(failKey, newFailures.toString(), { expirationTtl: 1800 });
      if (newFailures >= 10) {
        await env.RATE_LIMIT.put(`lock:${body.email.toLowerCase()}`, '1', { expirationTtl: 1800 });
      }
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'INVALID_CREDENTIALS',
            message: 'Invalid email or password',
          },
        } as ApiResponse),
        {
          status: 401,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    // Generate tokens
    const accessToken = await generateToken(user.id, 'access', env);
    const refreshToken = await generateToken(user.id, 'refresh', env);

    // Reset failure counter on success
    await env.RATE_LIMIT.delete(`authfail:${body.email.toLowerCase()}`);
    await env.RATE_LIMIT.delete(`lock:${body.email.toLowerCase()}`);
    
    // Remove password hash from response
    const { passwordHash: _, ...userWithoutPassword } = user;
    
    return new Response(
      JSON.stringify({
        success: true,
        data: {
          user: userWithoutPassword,
          tokens: {
            accessToken,
            refreshToken,
          },
        },
      } as ApiResponse),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Login error:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'Failed to login',
        },
      } as ApiResponse),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
};

export const logout: RouteHandler = async (_request, _env, _ctx, _params) => {
  // FIXME: Session invalidation to be implemented with token blacklist in KV
  return new Response(
    JSON.stringify({
      success: true,
      data: { message: 'Logged out successfully' },
    } as ApiResponse),
    {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    }
  );
};

// Refresh access token using a valid refresh token
export const refresh: RouteHandler = async (request, env, _ctx, _params) => {
  try {
    console.log('[refresh] Starting refresh token handler');
    console.log('[refresh] env.JWT_SECRET exists:', !!env.JWT_SECRET);
    console.log('[refresh] env keys:', Object.keys(env));
    
    const body = await request.json().catch(() => ({})) as Partial<RefreshBody>;
    const refreshToken = body.refreshToken;
    console.log('[refresh] Received refreshToken:', refreshToken ? `${refreshToken.substring(0, 20)}...` : 'MISSING');
    
    if (!refreshToken) {
      console.log('[refresh] Validation failed: no refreshToken provided');
      return new Response(
        JSON.stringify({
          success: false,
          error: { code: 'VALIDATION_ERROR', message: 'refreshToken required' },
        } as ApiResponse),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }
    
    console.log('[refresh] Verifying token...');
    const payload = await verifyToken(refreshToken, env);
    console.log('[refresh] Token verification result:', payload ? `userId=${payload.userId}, type=${payload.type}` : 'NULL');
    
    if (!payload || payload.type !== 'refresh') {
      console.log('[refresh] Token invalid or wrong type');
      return new Response(
        JSON.stringify({
          success: false,
          error: { code: 'UNAUTHORIZED', message: 'Invalid refresh token' },
        } as ApiResponse),
        { status: 401, headers: { 'Content-Type': 'application/json' } }
      );
    }
    
    // Rotate refresh token to reduce replay risk
    console.log('[refresh] Generating new tokens for userId:', payload.userId);
    const newAccess = await generateToken(payload.userId, 'access', env);
    console.log('[refresh] Generated new access token:', newAccess ? `${newAccess.substring(0, 20)}...` : 'FAILED');
    const newRefresh = await generateToken(payload.userId, 'refresh', env);
    console.log('[refresh] Generated new refresh token:', newRefresh ? `${newRefresh.substring(0, 20)}...` : 'FAILED');
    
    return new Response(
      JSON.stringify({
        success: true,
        data: { tokens: { accessToken: newAccess, refreshToken: newRefresh } },
      } as ApiResponse),
      { status: 200, headers: { 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('[refresh] Exception caught:', error);
    console.error('[refresh] Error stack:', error instanceof Error ? error.stack : 'No stack');
    console.error('[refresh] Error message:', error instanceof Error ? error.message : String(error));
    return new Response(
      JSON.stringify({
        success: false,
        error: { code: 'INTERNAL_ERROR', message: 'Failed to refresh token' },
      } as ApiResponse),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
};
