import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { verifyFirebaseToken } from '../utils/firebase-admin';
import { ValidationUtils, ErrorHandler, SecurityUtils } from '../../../../services/shared';

/**
 * Sync a Firebase-authenticated user into D1.
 * Body: { uid, email, username, displayName }
 */
export async function syncUser(req: Request, env: Env): Promise<Response> {
  try {
    // Guard: ensure required bindings exist
    if (!env?.DB) {
      return new Response(JSON.stringify({ success:false, error:{ code:'ENV_MISCONFIG', message:'DB binding missing' } }), { status:500, headers:{'Content-Type':'application/json'} });
    }
    const auth = req.headers.get('Authorization') || '';
    const token = auth.replace(/^Bearer\s+/i, '');
    if (!token) {
      return new Response(JSON.stringify({ success:false, error:{ code:'UNAUTHORIZED', message:'Missing token' } }), { status:401, headers:{'Content-Type':'application/json'} });
    }

    const fbUser = await verifyFirebaseToken(token, env);
    if (!fbUser) {
      return new Response(JSON.stringify({ success:false, error:{ code:'UNAUTHORIZED', message:'Invalid Firebase token' } }), { status:401, headers:{'Content-Type':'application/json'} });
    }

    const body = await req.json().catch(() => ({})) as any;
    const uid = body?.uid || (fbUser as any).uid;
    const email = body?.email || fbUser.email || null;
    const username = body?.username || null;
    const displayName = body?.displayName || null;

    await env.DB.prepare(`
      CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        email TEXT,
        username TEXT,
        display_name TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
      )
    `).run();

    const existing = await env.DB.prepare('SELECT id FROM users WHERE id = ?1').bind(uid).first();
    if (!existing) {
      await env.DB.prepare('INSERT INTO users (id, email, username, display_name) VALUES (?1, ?2, ?3, ?4)')
        .bind(uid, email, username, displayName)
        .run();
    } else {
      await env.DB.prepare('UPDATE users SET email = ?2, username = ?3, display_name = ?4 WHERE id = ?1')
        .bind(uid, email, username, displayName)
        .run();
    }

    return jsonResponse(true, { synced: true, uid });
  } catch (error) {
    console.error('[auth.sync] Error:', error);
    return new Response(JSON.stringify({ success:false, error:{ code:'INTERNAL_ERROR', message:'Failed to sync user' } }), { status:500, headers:{'Content-Type':'application/json'} });
  }
}
