// Ultra-fast request router with pattern matching

import type { Env, RouteHandler } from './types';
import { instrumentRequest } from './utils/otel';
import { requireAuth, optionalAuth, rateLimit } from './middleware/auth';
import * as authHandlers from './handlers/auth.handler';
import * as feedHandlers from './handlers/feed.handler';
import * as videoHandlers from './handlers/video.handler';
import * as userHandlers from './handlers/user.handler';
import * as adsHandlers from './handlers/ads.handler';
import * as liveHandlers from './handlers/live.handler.js';
import * as complianceHandlers from './handlers/compliance.handler.js';
import * as metricsHandlers from './handlers/metrics.handler.js';
import * as perfTelemetryHandler from './handlers/perf-telemetry.handler';
import { exportTelemetry } from './utils/telemetry_exporter';
import * as subscriptionHandlers from './handlers/subscription.handler.js';
import * as creatorHandlers from './handlers/creator.handler.js';
import * as payoutHandlers from './handlers/payout.handler';
import * as referralHandlers from './handlers/referral.handler';
import * as stripeWebhookHandler from './handlers/stripe-webhook.handler';
import * as agoraHandlers from './handlers/agora.handler';
import * as agoraTestHandler from './handlers/agora.test.handler';
import * as deviceTelemetryHandlers from './handlers/device-telemetry.handler';
import * as authSyncHandler from './handlers/auth.sync.handler';
import { handleChatWebSocket } from './ws/chat.websocket';
import { handleChatRequest } from './handlers/chat.handler.unified';
import { proxyBackend } from './handlers/backend-proxy.handler';

interface Route {
  method: string;
  pattern: RegExp;
  handler: RouteHandler;
  paramNames: string[];
}

const routes: Route[] = [];

export function addRoute(method: string, path: string, handler: RouteHandler): void {
  const paramNames: string[] = [];
  const pattern = path
    .replace(/\//g, '\\/')
    .replace(/:(\w+)/g, (_, name) => {
      paramNames.push(name);
      return '([^/]+)';
    });
  
  routes.push({
    method: method.toUpperCase(),
    pattern: new RegExp(`^${pattern}$`),
    handler,
    paramNames,
  });
}

export async function route(
  path: string,
  method: string,
  request: Request,
  env: Env,
  ctx: ExecutionContext
): Promise<Response> {
  for (const route of routes) {
    if (route.method !== method.toUpperCase()) continue;
    
    const match = path.match(route.pattern);
    if (!match) continue;
    
    const params: Record<string, string> = {};
    for (let i = 0; i < route.paramNames.length; i++) {
      params[route.paramNames[i]] = match[i + 1];
    }
    
    // Instrument each matched route for latency metrics
    const endpointTag = `route:${route.method}:${route.pattern.source}`;
    return await instrumentRequest(env, endpointTag, () => route.handler(request, env, ctx, params));
  }
  
  return new Response(
    JSON.stringify({
      success: false,
      error: {
        code: 'NOT_FOUND',
        message: 'Endpoint not found',
      },
    }),
    {
      status: 404,
      headers: { 'Content-Type': 'application/json' },
    }
  );
}

// Define all routes
export function setupRoutes(): void {
  // Root endpoint (for browser/index checks)
  addRoute('GET', '/', async () => {
    return new Response(
      JSON.stringify({
        success: true,
        data: {
          name: 'Spaktok API',
          version: '1.0.0',
          status: 'running',
          timestamp: Date.now(),
        },
      }),
      { headers: { 'Content-Type': 'application/json' } }
    );
  });

  // Health check
  const healthHandler = async () => {
    return new Response(
      JSON.stringify({
        success: true,
        data: { status: 'healthy', timestamp: Date.now() },
      }),
      { headers: { 'Content-Type': 'application/json' } }
    );
  };
  
  addRoute('GET', '/health', healthHandler);
  addRoute('GET', '/healthz', healthHandler); // K8s/watchdog convention
  
  // Auth routes (public, with rate limiting)
  addRoute('POST', '/auth/register', rateLimit(5, 300)(authHandlers.register));
  addRoute('POST', '/auth/login', rateLimit(5, 300)(authHandlers.login));
  addRoute('POST', '/auth/refresh', rateLimit(20, 300)(authHandlers.refresh));
  addRoute('POST', '/auth/logout', requireAuth(authHandlers.logout));
  
  // Feed routes (optional auth for personalization)
  addRoute('GET', '/feed/foryou', optionalAuth(feedHandlers.forYou));
  addRoute('GET', '/feed/following', requireAuth(feedHandlers.following));
  
  // Live feed routes
  const liveFeedHandlers = require('./handlers/live-feed.handler');
  addRoute('GET', '/feed/live', optionalAuth(liveFeedHandlers.getLiveFeed));
  addRoute('GET', '/feed/live/trending', optionalAuth(liveFeedHandlers.getTrendingLive));
  addRoute('GET', '/feed/live/category/:category', optionalAuth(liveFeedHandlers.getLiveByCategory));
  addRoute('GET', '/feed/live/search', optionalAuth(liveFeedHandlers.searchLiveStreams));
  addRoute('POST', '/live/batch-stats', optionalAuth(liveFeedHandlers.batchLiveStats));
  
  // Video routes (protected)
  addRoute('POST', '/videos/upload', requireAuth(videoHandlers.upload));
  addRoute('GET', '/videos/:id', optionalAuth(videoHandlers.get));
  addRoute('GET', '/videos/:id/processing-status', requireAuth(videoHandlers.getProcessingStatus));
  addRoute('POST', '/videos/:id/like', requireAuth(videoHandlers.like));
  addRoute('DELETE', '/videos/:id/like', requireAuth(videoHandlers.unlike));
  addRoute('POST', '/videos/:id/comments', requireAuth(videoHandlers.addComment));
  
  // User routes (protected)
  addRoute('GET', '/users/me', requireAuth(userHandlers.me));
  addRoute('GET', '/users/:id', optionalAuth(userHandlers.get));
  addRoute('PATCH', '/users/:id', requireAuth(userHandlers.update));
  addRoute('POST', '/users/:id/follow', requireAuth(userHandlers.follow));
  addRoute('DELETE', '/users/:id/unfollow', requireAuth(userHandlers.unfollow));
  
  // Chat routes with unified handler (protected)
  // ✅ Single handler manages all chat operations
  addRoute('GET', '/chat/conversations', requireAuth(handleChatRequest));
  addRoute('GET', '/chat/messages', requireAuth(handleChatRequest));
  addRoute('POST', '/chat/messages', requireAuth(handleChatRequest));
  addRoute('POST', '/chat/typing', requireAuth(handleChatRequest));
  addRoute('POST', '/chat/presence', requireAuth(handleChatRequest));
  addRoute('GET', '/chat/presence', requireAuth(handleChatRequest));
  addRoute('POST', '/chat/read', requireAuth(handleChatRequest));
  
  // Adaptive Ad System routes (optional auth for targeting)
  addRoute('GET', '/ads/feed', optionalAuth(adsHandlers.getAdsForFeed));
  addRoute('POST', '/ads/impression', optionalAuth(adsHandlers.trackImpression));
  addRoute('POST', '/ads/click', optionalAuth(adsHandlers.trackClick));
  addRoute('GET', '/ads/pricing/tiers', requireAuth(adsHandlers.getPricingTiers));
  addRoute('GET', '/ads/pricing/recommend', requireAuth(adsHandlers.getRecommendedPricing));
  
  // Advertiser routes (protected)
  addRoute('POST', '/advertisers/register', requireAuth(adsHandlers.createAdvertiserAccount));
  addRoute('GET', '/advertisers/dashboard', requireAuth(adsHandlers.getAdvertiserDashboard));
  addRoute('POST', '/advertisers/campaigns', requireAuth(adsHandlers.createCampaign));
  addRoute('GET', '/advertisers/campaigns/:campaignId/analytics', requireAuth(adsHandlers.getCampaignAnalytics));
  addRoute('POST', '/advertisers/campaigns/:campaignId/creatives', requireAuth(adsHandlers.uploadCreative));

  // Live streaming (protected, Durable Object backed)
  addRoute('POST', '/live/:streamId/join', requireAuth(liveHandlers.joinStream));
  addRoute('POST', '/live/:streamId/leave', requireAuth(liveHandlers.leaveStream));
  addRoute('POST', '/live/:streamId/gift', requireAuth(liveHandlers.sendStreamGift));
  addRoute('GET', '/live/:streamId/state', optionalAuth(liveHandlers.getStreamState));
  addRoute('POST', '/live/:streamId/presence', requireAuth(liveHandlers.updatePresence));

  // Compliance endpoints (protected)
  addRoute('POST', '/compliance/consent', requireAuth(complianceHandlers.recordConsent));
  addRoute('GET', '/compliance/consent/:userId', requireAuth(complianceHandlers.getConsent));
  addRoute('DELETE', '/compliance/consent/:userId', requireAuth(complianceHandlers.withdrawConsent));
  addRoute('DELETE', '/compliance/erase/:userId', requireAuth(complianceHandlers.eraseUserData));
  addRoute('POST', '/compliance/age', requireAuth(complianceHandlers.recordAgeVerification));

  // Economic / metrics dashboards (protected)
  addRoute('GET', '/metrics/economy/summary', requireAuth(metricsHandlers.getEconomySummary));
  addRoute('GET', '/metrics/economy/gifts/top', requireAuth(metricsHandlers.getTopGifters));
  addRoute('GET', '/metrics/perf/latency', requireAuth(metricsHandlers.getLatencySnapshot));
  addRoute('GET', '/metrics/economy/subscriptions', requireAuth(metricsHandlers.getSubscriptionSummary));
  // Perf telemetry ingestion (debug/profile; optional auth)
  addRoute('POST', '/metrics/perf/latency', optionalAuth(perfTelemetryHandler.postPerfTelemetry));
  // Creator analytics (protected)
  addRoute('GET', '/creator/:userId/analytics', requireAuth(creatorHandlers.getCreatorAnalytics));
  // Compliance audit (protected)
  addRoute('GET', '/compliance/audit/:userId', requireAuth(complianceHandlers.auditUserCompliance));

  // Subscription / VIP (protected)
  addRoute('POST', '/subscriptions/plans', requireAuth(subscriptionHandlers.createPlan));
  addRoute('GET', '/subscriptions/plans', optionalAuth(subscriptionHandlers.listPlans));
  addRoute('POST', '/subscriptions/subscribe', requireAuth(subscriptionHandlers.subscribe));
  addRoute('POST', '/subscriptions/cancel', requireAuth(subscriptionHandlers.cancelSubscription));
  addRoute('GET', '/subscriptions/me', requireAuth(subscriptionHandlers.mySubscription));
  addRoute('GET', '/subscriptions/feature', requireAuth(subscriptionHandlers.checkFeatureGate));

  // Payout & KYC (protected)
  addRoute('POST', '/payouts/request', requireAuth(payoutHandlers.requestPayout));
  addRoute('GET', '/payouts/ledger/:userId', requireAuth(payoutHandlers.getLedger));
  addRoute('POST', '/payouts/kyc', requireAuth(payoutHandlers.submitKyc));

  // Referral system (protected)
  addRoute('POST', '/referral/code', requireAuth(referralHandlers.createCode));
  addRoute('POST', '/referral/activate', requireAuth(referralHandlers.activateCode));
  addRoute('GET', '/referral/stats/:code', requireAuth(referralHandlers.getStats));

  // Agora (protected; token issuance)
  addRoute('POST', '/agora/token', requireAuth(agoraHandlers.generateToken));
  addRoute('POST', '/agora/renew-token', requireAuth(agoraHandlers.renewToken));
  addRoute('GET', '/agora/health', agoraHandlers.health); // Public health check
  
  // TEST ONLY: Remove before production!
  addRoute('POST', '/agora/test-token', agoraTestHandler.testAgoraToken);

  // Backend proxy (CF ➜ BE routing map)
  addRoute('GET', '/backend/health', proxyBackend);
  addRoute('POST', '/backend/ai-job', proxyBackend);
  addRoute('POST', '/backend/compliance-log', proxyBackend);
  
  // Stripe webhooks (no auth required - signature verification in handler)
  addRoute('POST', '/webhooks/stripe', stripeWebhookHandler.handleStripeWebhook);

  // Telemetry snapshot (protected)
  addRoute('GET', '/metrics/telemetry', requireAuth(async (_req, env) => {
    const snap = await exportTelemetry(env);
    return new Response(JSON.stringify({ success: true, data: snap }), { headers: { 'Content-Type': 'application/json' } });
  }));

  // Device telemetry (client metrics from Flutter/mobile)
  addRoute('POST', '/metrics/device', requireAuth(deviceTelemetryHandlers.receiveDeviceMetrics));
  addRoute('GET', '/metrics/device/aggregates', requireAuth(deviceTelemetryHandlers.getDeviceMetricsAggregates));

  // Auth sync (Firebase-authenticated clients)
  addRoute('POST', '/auth/sync', requireAuth(authSyncHandler.syncUser));

  // WebSocket chat (protected, roomId path param)
  addRoute('GET', '/chat/ws/:roomId', requireAuth(handleChatWebSocket));
  // Region analytics stats (global DO) - protected
  addRoute('GET', '/chat/regions/stats', requireAuth(async (_req, env) => {
    if (!env.CHAT_ROOM) return new Response(JSON.stringify({ success:false, error:{ code:'CONFIG_ERROR', message:'CHAT_ROOM binding missing'} }), { status:500, headers:{'Content-Type':'application/json'} });
    const id = env.CHAT_ROOM.idFromName('global-chat');
    const stub = env.CHAT_ROOM.get(id);
    const res = await stub.fetch('https://do/global-chat/stats');
    return res;
  }));
}
