// Middleware for CORS, auth, rate limiting, etc.

import type { Env, Middleware, JWTPayload } from './types';
import { isCountryRestricted } from './utils/guard';
import { verifyToken } from './utils/jwt.utils';
import { verifyFirebaseToken, getOrCreateUserFromFirebase } from './utils/firebase-admin';
import { startSpan, endSpan } from './utils/otel';

// Constants for endpoint-specific limits
const GLOBAL_RATE_LIMIT = 100; // per IP per minute
const LOGIN_RATE_LIMIT = 5; // per IP per minute
const REGISTER_RATE_LIMIT = 3; // per IP per minute
const LOGIN_FAIL_LOCK_THRESHOLD = 10; // failed attempts before lock
const LOGIN_FAIL_WINDOW_SECONDS = 1800; // 30 min lock window

// CORS middleware
export const corsMiddleware: Middleware = async (request, env) => {
  const origin = env.FRONTEND_ORIGIN || '*';
  if (request.method === 'OPTIONS') {
    return new Response(null, {
      headers: {
        'Access-Control-Allow-Origin': origin,
        'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Actor, X-Request-ID, X-Flow-ID',
        'Access-Control-Max-Age': '86400',
      },
    });
  }
  return null;
};

// Rate limiting middleware
export const rateLimitMiddleware: Middleware = async (request, env) => {
  const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
  const url = new URL(request.url);
  const path = url.pathname;

  // Determine limit based on endpoint
  let limit = GLOBAL_RATE_LIMIT;
  let bucket = 'global';

  if (path.startsWith('/auth/login')) {
    limit = LOGIN_RATE_LIMIT;
    bucket = 'login';
  } else if (path.startsWith('/auth/register')) {
    limit = REGISTER_RATE_LIMIT;
    bucket = 'register';
  }

  const key = `rate:${bucket}:${ip}`;
  const current = await env.RATE_LIMIT.get(key);
  const count = current ? Number.parseInt(current, 10) : 0;

  if (count >= limit) {
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'RATE_LIMIT_EXCEEDED',
          message: 'Too many requests, slow down',
          bucket,
          limit,
        },
      }),
      {
        status: 429,
        headers: {
          'Content-Type': 'application/json',
          'Retry-After': '60',
        },
      }
    );
  }

  await env.RATE_LIMIT.put(key, (count + 1).toString(), { expirationTtl: 60 });
  return null;
};

// Auth middleware (for protected routes)
// Supports both Firebase ID tokens and Workers JWT tokens
export async function requireAuth(request: Request, env: Env): Promise<JWTPayload | Response> {
  const authHeader = request.headers.get('Authorization');
  
  if (!authHeader?.startsWith('Bearer ')) {
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'UNAUTHORIZED',
          message: 'Missing or invalid authorization header',
        },
      }),
      {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
  
  const token = authHeader.substring(7);
  
  // First, try to verify as Firebase token
  if (env.FIREBASE_PROJECT_ID) {
    try {
      const firebaseUser = await verifyFirebaseToken(token, env);
      
      if (firebaseUser) {
        // Valid Firebase token - get or create user in D1
        const user = await getOrCreateUserFromFirebase(env, firebaseUser);
        
        if (user) {
          // Return JWT payload format for compatibility
          return {
            userId: user.id,
            type: 'access',
            iat: Math.floor(Date.now() / 1000),
            exp: Math.floor(Date.now() / 1000) + 3600,
          };
        }
      }
    } catch (error) {
      // Not a Firebase token or verification failed, try Workers JWT
      console.debug('Firebase token verification failed, trying Workers JWT:', error);
    }
  }
  
  // Fallback to Workers JWT verification
  try {
    const payload = await verifyToken(token, env);
    
    if (payload?.type !== 'access') {
      throw new Error('Invalid token type');
    }
    
    return payload;
  } catch (error) {
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'INVALID_TOKEN',
          message: 'Invalid or expired token',
        },
      }),
      {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
}

// Apply all middleware
export async function applyMiddleware(
  request: Request,
  env: Env,
  ctx: ExecutionContext
): Promise<Response | null> {
  const corsSpan = startSpan('middleware.cors');
  const corsResult = await corsMiddleware(request, env, ctx);
  await endSpan(env, corsSpan, 'cors');
  if (corsResult) return corsResult;

  const rateSpan = startSpan('middleware.rate');
  const rateLimitResult = await rateLimitMiddleware(request, env, ctx);
  await endSpan(env, rateSpan, 'rateLimit');
  if (rateLimitResult) return rateLimitResult;

  // Restricted country check (using Cloudflare geo header CF-IPCountry)
  const geo = request.headers.get('CF-IPCountry');
  if (geo) {
    const restricted = await isCountryRestricted(env, geo);
    if (restricted) {
      return new Response(JSON.stringify({ success: false, error: { code: 'REGION_BLOCKED', message: 'Service not available in your country' } }), { status: 451, headers: { 'Content-Type': 'application/json' } });
    }
  }

  return null;
}

// Add CORS headers to response
export function addCorsHeaders(response: Response, env?: Env): Response {
  const origin = env?.FRONTEND_ORIGIN || '*';
  const newHeaders = new Headers(response.headers);
  newHeaders.set('Access-Control-Allow-Origin', origin);
  newHeaders.set('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  newHeaders.set('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Actor, X-Request-ID, X-Flow-ID');
  
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers: newHeaders,
  });
}
