/**
 * UNIFIED PIPELINE - Single request processing path
 * 
 * ✅ Consolidates:
 * - All request types (HTTP, WebSocket)
 * - All handlers (chat, video, feed, etc)
 * - All middlewares
 * - Unified telemetry & tracing
 * - Priority queuing
 * 
 * Flow: Ingress → Validation → Routing → Caching → Execution → Egress
 */

import type { ExecutionContext } from '@cloudflare/workers-types';
import type { Env } from '../types';

// ============================================================================
// TYPES
// ============================================================================

export enum RequestPriority {
  CRITICAL = 0,      // User actions (send message, join stream)
  HIGH = 1,           // Content fetch (reels, feed)
  NORMAL = 2,         // Background ops (analytics, cleanup)
  LOW = 3,            // Analytics, non-critical
}

export enum PipelineStage {
  INGRESS = 'ingress',
  VALIDATION = 'validation',
  AUTH = 'auth',
  ROUTING = 'routing',
  CACHE_CHECK = 'cache_check',
  RATE_LIMIT = 'rate_limit',
  EXECUTION = 'execution',
  CACHE_STORE = 'cache_store',
  TELEMETRY = 'telemetry',
  EGRESS = 'egress',
}

interface StageMetrics {
  name: PipelineStage;
  startTime: number;
  endTime?: number;
  duration?: number;
  error?: string;
}

export interface PipelineContext {
  id: string;                         // Unique request ID
  traceId: string;                    // Distributed trace ID
  priority: RequestPriority;          // Request priority
  stages: StageMetrics[];             // Timing data for each stage
  metadata: Map<string, any>;         // Custom metadata
  
  // Request info
  method: string;
  path: string;
  headers: Map<string, string>;
  
  // Auth info
  userId?: string;
  token?: string;
  
  // Response
  response?: Response;
  cachedResponse?: boolean;
  
  // Errors
  error?: Error;
}

// ============================================================================
// UNIFIED PIPELINE CLASS
// ============================================================================

export class UnifiedPipeline {
  private env: Env;
  private ctx: ExecutionContext;
  private context: PipelineContext;

  constructor(env: Env, ctx: ExecutionContext, request: Request) {
    this.env = env;
    this.ctx = ctx;
    
    const url = new URL(request.url);
    const headers = new Map<string, string>();
    request.headers.forEach((value, key) => headers.set(key, value));

    this.context = {
      id: crypto.randomUUID(),
      traceId: request.headers.get('x-trace-id') ?? `trace-${Date.now()}`,
      priority: this.determinePriority(request),
      stages: [],
      metadata: new Map(),
      method: request.method,
      path: url.pathname,
      headers,
    };
  }

  // ========================================================================
  // STAGE EXECUTION
  // ========================================================================

  async execute(handler: (ctx: PipelineContext) => Promise<Response>): Promise<Response> {
    try {
      // Stage 1: Ingress (measure entry time)
      await this.executeStage(PipelineStage.INGRESS, async () => {
        this.context.metadata.set('requestTime', Date.now());
        this.context.metadata.set('userAgent', this.context.headers.get('user-agent'));
      });

      // Stage 2: Validation
      await this.executeStage(PipelineStage.VALIDATION, async () => {
        if (!this.context.path || !this.context.method) {
          throw new Error('Invalid request: missing path or method');
        }
      });

      // Stage 3: Auth (if needed)
      await this.executeStage(PipelineStage.AUTH, async () => {
        const authHeader = this.context.headers.get('authorization');
        if (authHeader?.startsWith('Bearer ')) {
          this.context.token = authHeader.slice(7);
          // Token verification would happen here
        }
      });

      // Stage 4: Routing
      await this.executeStage(PipelineStage.ROUTING, async () => {
        this.context.metadata.set('route', this.determineRoute(this.context.path));
      });

      // Stage 5: Cache Check
      let cachedResponse: Response | null = null;
      await this.executeStage(PipelineStage.CACHE_CHECK, async () => {
        const cacheKey = this.generateCacheKey();
        if (this.isCacheable()) {
          cachedResponse = await this.env.CACHE.match(cacheKey);
          if (cachedResponse) {
            this.context.cachedResponse = true;
          }
        }
      });

      if (cachedResponse) {
        this.context.response = cachedResponse;
        await this.executeStage(PipelineStage.EGRESS, () => Promise.resolve());
        return cachedResponse;
      }

      // Stage 6: Rate Limiting
      await this.executeStage(PipelineStage.RATE_LIMIT, async () => {
        const rateLimitKey = `rl:${this.context.userId || this.context.headers.get('x-forwarded-for')}`;
        const current = await this.env.KV.get(rateLimitKey);
        const count = current ? parseInt(current) + 1 : 1;
        
        if (count > 1000) { // 1000 req/min per user
          throw new Error('Rate limit exceeded');
        }
        
        await this.env.KV.put(rateLimitKey, count.toString(), { expirationTtl: 60 });
      });

      // Stage 7: Execute handler
      await this.executeStage(PipelineStage.EXECUTION, async () => {
        this.context.response = await handler(this.context);
      });

      // Stage 8: Cache storage (if applicable)
      await this.executeStage(PipelineStage.CACHE_STORE, async () => {
        if (this.isCacheable() && this.context.response) {
          const cacheKey = this.generateCacheKey();
          const cacheControl = this.getCacheControl();
          
          const cachedResponse = new Response(this.context.response.body, {
            status: this.context.response.status,
            headers: {
              ...Object.fromEntries(this.context.response.headers),
              'cache-control': cacheControl,
            },
          });
          
          this.ctx.waitUntil(this.env.CACHE.put(cacheKey, cachedResponse));
        }
      });

      // Stage 9: Emit telemetry
      await this.executeStage(PipelineStage.TELEMETRY, async () => {
        this.emitMetrics();
      });

      // Stage 10: Egress (finalize response)
      await this.executeStage(PipelineStage.EGRESS, async () => {
        if (!this.context.response) {
          throw new Error('Handler did not produce response');
        }
      });

      return this.context.response!;
    } catch (error) {
      // Error handling
      return this.handleError(error as Error);
    }
  }

  private async executeStage(
    stage: PipelineStage,
    fn: () => Promise<void>
  ): Promise<void> {
    const startTime = performance.now();
    const metrics: StageMetrics = {
      name: stage,
      startTime,
    };

    try {
      await fn();
      metrics.endTime = performance.now();
      metrics.duration = metrics.endTime - startTime;
    } catch (error) {
      metrics.error = (error as Error).message;
      metrics.duration = performance.now() - startTime;
      throw error;
    } finally {
      this.context.stages.push(metrics);
    }
  }

  // ========================================================================
  // UTILITY METHODS
  // ========================================================================

  private determinePriority(request: Request): RequestPriority {
    const path = new URL(request.url).pathname;

    // Critical: real-time operations
    if (path.includes('/chat/') || path.includes('/live/')) {
      return RequestPriority.CRITICAL;
    }

    // High: content fetch
    if (path.includes('/feed') || path.includes('/reels')) {
      return RequestPriority.HIGH;
    }

    // Normal: user data, setup
    if (path.includes('/user') || path.includes('/auth')) {
      return RequestPriority.NORMAL;
    }

    // Low: analytics, cleanup
    return RequestPriority.LOW;
  }

  private determineRoute(path: string): string {
    if (path.includes('/chat')) return 'chat';
    if (path.includes('/live')) return 'live';
    if (path.includes('/feed')) return 'feed';
    if (path.includes('/reels')) return 'reels';
    if (path.includes('/video')) return 'video';
    if (path.includes('/user')) return 'user';
    return 'unknown';
  }

  private isCacheable(): boolean {
    // Only cache GET requests
    if (this.context.method !== 'GET') return false;

    // Don't cache auth endpoints
    if (this.context.path.includes('/auth')) return false;

    // Don't cache real-time endpoints
    if (this.context.path.includes('/chat/ws')) return false;
    if (this.context.path.includes('/live/ws')) return false;

    return true;
  }

  private generateCacheKey(): string {
    const user = this.context.userId || 'anonymous';
    return `cache:${user}:${this.context.method}:${this.context.path}`;
  }

  private getCacheControl(): string {
    const route = this.context.metadata.get('route');
    const cacheStrategies: Record<string, string> = {
      'chat': 'max-age=0, must-revalidate',      // No cache for real-time
      'live': 'max-age=0, must-revalidate',      // No cache for real-time
      'feed': 'max-age=300, stale-while-revalidate=3600', // 5 min cache
      'reels': 'max-age=3600, stale-while-revalidate=86400', // 1 hour cache
      'video': 'max-age=86400',                  // 24 hour cache
      'user': 'max-age=300, stale-while-revalidate=3600', // 5 min cache
    };
    return cacheStrategies[route] || 'max-age=60';
  }

  private emitMetrics(): void {
    const totalDuration = this.context.stages.reduce(
      (sum, s) => sum + (s.duration || 0),
      0
    );

    const metrics = {
      requestId: this.context.id,
      traceId: this.context.traceId,
      totalDuration: totalDuration.toFixed(2),
      priority: RequestPriority[this.context.priority],
      route: this.context.metadata.get('route'),
      cached: this.context.cachedResponse,
      stages: this.context.stages.map(s => ({
        name: s.name,
        duration: s.duration?.toFixed(2),
        error: s.error,
      })),
    };

    // Log to console (would send to external logging service)
    console.log(JSON.stringify({
      level: 'INFO',
      type: 'PIPELINE_METRICS',
      ...metrics,
      timestamp: new Date().toISOString(),
    }));

    // Only log slow requests or errors
    if (totalDuration > 1000 || this.context.error) {
      console.error(JSON.stringify({
        level: 'WARN',
        type: 'SLOW_REQUEST',
        ...metrics,
        timestamp: new Date().toISOString(),
      }));
    }
  }

  private handleError(error: Error): Response {
    console.error(JSON.stringify({
      level: 'ERROR',
      type: 'PIPELINE_ERROR',
      requestId: this.context.id,
      traceId: this.context.traceId,
      error: error.message,
      stack: error.stack,
      timestamp: new Date().toISOString(),
    }));

    const statusCode = error.message.includes('Rate limit') ? 429 :
                       error.message.includes('Unauthorized') ? 401 :
                       error.message.includes('Not found') ? 404 : 500;

    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: this.getErrorCode(statusCode),
          message: error.message,
          requestId: this.context.id,
        },
      }),
      {
        status: statusCode,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }

  private getErrorCode(status: number): string {
    const codes: Record<number, string> = {
      400: 'BAD_REQUEST',
      401: 'UNAUTHORIZED',
      403: 'FORBIDDEN',
      404: 'NOT_FOUND',
      429: 'RATE_LIMITED',
      500: 'INTERNAL_ERROR',
    };
    return codes[status] || 'UNKNOWN_ERROR';
  }

  // ========================================================================
  // PUBLIC API
  // ========================================================================

  getContext(): PipelineContext {
    return this.context;
  }

  setUserId(userId: string): void {
    this.context.userId = userId;
  }

  addMetadata(key: string, value: any): void {
    this.context.metadata.set(key, value);
  }

  getMetrics(): {
    totalDuration: number;
    stages: StageMetrics[];
    priority: string;
  } {
    const totalDuration = this.context.stages.reduce(
      (sum, s) => sum + (s.duration || 0),
      0
    );
    return {
      totalDuration,
      stages: this.context.stages,
      priority: RequestPriority[this.context.priority],
    };
  }
}

