// Video handlers for upload, retrieval, and interactions

import type { RouteHandler } from '../types';
import { ApiResponse } from '../types';
import { DatabaseService } from '../services/db.service';
import { StorageService } from '../services/storage.service';
import { CacheService } from '../services/cache.service';
import { AnalyticsService } from '../services/analytics.service';
import { VideoProcessingService } from '../services/video-processing.service';
import { requireAuth } from '../middleware';
import { withSpan } from '../utils/otel_wrapper';
import { ensureMinimumAgeRegionAware } from '../utils/guard';
import { ValidationUtils, ErrorHandler } from '../../../../services/shared';

const uploadCore: RouteHandler = async (request, env, ctx, _params) => {
    // Guard: ensure required bindings exist
    if (!env?.DB) {
      return new Response(
        JSON.stringify({ success:false, error:{ code:'ENV_MISCONFIG', message:'DB binding missing' } }),
        { status:500, headers:{ 'Content-Type':'application/json' } }
      );
    }
    if (!env?.R2) {
      return new Response(
        JSON.stringify({ success:false, error:{ code:'ENV_MISCONFIG', message:'R2 binding missing' } }),
        { status:500, headers:{ 'Content-Type':'application/json' } }
      );
    }
    // Verify authentication
    const authResult = await requireAuth(request, env);
    if (authResult instanceof Response) return authResult;
    
    const userId = authResult.userId;
    // Region-aware age gating for video upload (requires minimum regional posting age, typically 13+; financial/content monetization may mandate 18+ in some regions)
    const ageCheck = await ensureMinimumAgeRegionAware(env, userId, { ip: request.headers.get('cf-connecting-ip') || undefined });
    if (!ageCheck.allowed) {
      return new Response(
        JSON.stringify({ success: false, error: { code: 'AGE_RESTRICTED', message: 'User does not meet regional minimum age requirements for uploading.' } }),
        { status: 403, headers: { 'Content-Type': 'application/json' } }
      );
    }
    
    try {
    const formData = await request.formData();
    const videoFile = formData.get('video') as File;
    const title = formData.get('title') as string;
    const description = formData.get('description') as string | null;
    const hashtagsStr = formData.get('hashtags') as string | null;
    
    if (!videoFile || !title) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'VALIDATION_ERROR',
            message: 'Video file and title are required',
          },
        } as ApiResponse),
        {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    const videoId = crypto.randomUUID();
    const storage = new StorageService(env);
    const db = new DatabaseService(env);
    const cache = new CacheService(env);
    const analytics = new AnalyticsService(env);
    
    // Upload video to R2
    const videoBuffer = await videoFile.arrayBuffer();
    const { url: videoUrl } = await storage.uploadVideo(
      videoId,
      videoBuffer,
      videoFile.type
    );
    
    // Generate thumbnail (simplified - in production use video processing)
    const thumbnailUrl = `https://storage.spaktok.com/thumbnails/${videoId}/thumb.jpg`;
    
    // Parse hashtags
    let hashtags: string[] | undefined = undefined;
    if (hashtagsStr) {
      try { hashtags = JSON.parse(hashtagsStr); } catch { hashtags = undefined; }
    }
    
    // Create video entry in database
    const video = await db.createVideo({
      userId,
      title,
      description: description || undefined,
      videoUrl,
      thumbnailUrl,
      // Provide sensible defaults for required counters and status; duration will be updated by processing pipeline
      duration: 0,
      likesCount: 0,
      viewsCount: 0,
      commentsCount: 0,
      sharesCount: 0,
      processingStatus: 'pending',
      width: 1080,
      height: 1920,
      hashtags,
    });
    
    // Log analytics
    ctx.waitUntil(
      analytics.logVideoUpload(videoId, userId, videoBuffer.byteLength, 0)
    );
    
    // Invalidate feed cache
    ctx.waitUntil(cache.invalidateFeed(null));
    
    // Trigger async video processing (GPU transcoding, thumbnail generation)
    const processingService = new VideoProcessingService(env);
    ctx.waitUntil(
      processingService.startProcessing(videoId, userId, videoUrl, videoBuffer.byteLength)
        .then(() => processingService.completeProcessing(videoId))
        .catch(error => {
          console.error('Video processing failed:', error);
          processingService.failProcessing(videoId, error);
        })
    );
    
    return new Response(
      JSON.stringify({
        success: true,
        data: {
          video,
          message: 'Video uploaded successfully. Processing in progress.',
          processingStatus: 'pending',
        },
      } as ApiResponse),
      {
        status: 201,
        headers: { 'Content-Type': 'application/json' },
      }
    );
    } catch (error) {
      console.error('Video upload error:', error);
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'INTERNAL_ERROR',
            message: 'Failed to upload video',
          },
        } as ApiResponse),
        {
          status: 500,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
};

export const upload: RouteHandler = withSpan(uploadCore, 'video.upload');

export const get: RouteHandler = async (request, env, ctx, params) => {
  try {
    const videoId = params.id as string;
    if (!env?.DB) {
      return new Response(JSON.stringify({ success:false, error:{ code:'ENV_MISCONFIG', message:'DB binding missing' } }), { status:500, headers:{'Content-Type':'application/json'} });
    }
    
    if (!videoId) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'VALIDATION_ERROR',
            message: 'Video ID is required',
          },
        } as ApiResponse),
        {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    const cache = new CacheService(env);
    const db = new DatabaseService(env);
    const analytics = new AnalyticsService(env);
    
    // Try cache first
    let video = await cache.getVideo(videoId);
    
    if (!video) {
      // Cache miss - fetch from DB
      const result = await env.DB.prepare(
        'SELECT * FROM videos WHERE id = ?'
      ).bind(videoId).first();
      
      if (!result) {
        return new Response(
          JSON.stringify({
            success: false,
            error: {
              code: 'NOT_FOUND',
              message: 'Video not found',
            },
          } as ApiResponse),
          {
            status: 404,
            headers: { 'Content-Type': 'application/json' },
          }
        );
      }
      
      video = result;
      
      // Cache for future requests
      ctx.waitUntil(cache.cacheVideo(videoId, video));
    }
    
    // Log view
    ctx.waitUntil(analytics.logVideoView(videoId));
    
    return new Response(
      JSON.stringify({
        success: true,
        data: { video },
      } as ApiResponse),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Get video error:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'Failed to retrieve video',
        },
      } as ApiResponse),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
};

export const like: RouteHandler = async (request, env, ctx, params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;
  const videoId = params.id as string;
  if (!env?.DB) {
    return new Response(JSON.stringify({ success:false, error:{ code:'ENV_MISCONFIG', message:'DB binding missing' } }), { status:500, headers:{'Content-Type':'application/json'} });
  }
  
  try {
    // Insert like
    await env.DB.prepare(
      'INSERT OR IGNORE INTO likes (user_id, video_id, created_at) VALUES (?, ?, ?)'
    ).bind(userId, videoId, new Date().toISOString()).run();
    
    // Increment likes count
    await env.DB.prepare(
      'UPDATE videos SET likes_count = likes_count + 1 WHERE id = ?'
    ).bind(videoId).run();
    
    // Invalidate cache
    const cache = new CacheService(env);
    ctx.waitUntil(cache.invalidateVideo(videoId));
    
    // Log action
    const analytics = new AnalyticsService(env);
    ctx.waitUntil(analytics.logUserAction('like', userId, videoId));
    
    return new Response(
      JSON.stringify({
        success: true,
        data: { message: 'Video liked successfully' },
      } as ApiResponse),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Like video error:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'Failed to like video',
        },
      } as ApiResponse),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
};

export const unlike: RouteHandler = async (request, env, ctx, params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;
  const videoId = params.id as string;
  if (!env?.DB) {
    return new Response(JSON.stringify({ success:false, error:{ code:'ENV_MISCONFIG', message:'DB binding missing' } }), { status:500, headers:{'Content-Type':'application/json'} });
  }
  
  try {
    // Delete like
    await env.DB.prepare(
      'DELETE FROM likes WHERE user_id = ? AND video_id = ?'
    ).bind(userId, videoId).run();
    
    // Decrement likes count
    await env.DB.prepare(
      'UPDATE videos SET likes_count = likes_count - 1 WHERE id = ? AND likes_count > 0'
    ).bind(videoId).run();
    
    // Invalidate cache
    const cache = new CacheService(env);
    ctx.waitUntil(cache.invalidateVideo(videoId));
    
    return new Response(
      JSON.stringify({
        success: true,
        data: { message: 'Video unliked successfully' },
      } as ApiResponse),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Unlike video error:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'Failed to unlike video',
        },
      } as ApiResponse),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
};

export const addComment: RouteHandler = async (request, env, ctx, params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;
  const videoId = params.id as string;
  if (!env?.DB) {
    return new Response(JSON.stringify({ success:false, error:{ code:'ENV_MISCONFIG', message:'DB binding missing' } }), { status:500, headers:{'Content-Type':'application/json'} });
  }
  
  try {
    const body = await request.json().catch(() => ({})) as { content: string };
    
    if (!body.content) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'VALIDATION_ERROR',
            message: 'Comment content is required',
          },
        } as ApiResponse),
        {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    const commentId = crypto.randomUUID();
    const now = new Date().toISOString();
    
    // Insert comment
    await env.DB.prepare(
      `INSERT INTO comments (id, video_id, user_id, content, likes_count, replies_count, created_at, updated_at)
       VALUES (?, ?, ?, ?, 0, 0, ?, ?)`
    ).bind(commentId, videoId, userId, body.content, now, now).run();
    
    // Increment comments count
    await env.DB.prepare(
      'UPDATE videos SET comments_count = comments_count + 1 WHERE id = ?'
    ).bind(videoId).run();
    
    // Invalidate cache
    const cache = new CacheService(env);
    ctx.waitUntil(cache.invalidateVideo(videoId));
    
    // Log action
    const analytics = new AnalyticsService(env);
    ctx.waitUntil(analytics.logUserAction('comment', userId, videoId));
    
    return new Response(
      JSON.stringify({
        success: true,
        data: {
          comment: {
            id: commentId,
            videoId,
            userId,
            content: body.content,
            likesCount: 0,
            repliesCount: 0,
            createdAt: now,
            updatedAt: now,
          },
        },
      } as ApiResponse),
      {
        status: 201,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Add comment error:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'Failed to add comment',
        },
      } as ApiResponse),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
};

/**
 * Get video processing status
 */
export const getProcessingStatus: RouteHandler = async (request, env, _ctx, params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const videoId = params.id as string;
  if (!env?.DB) {
    return new Response(JSON.stringify({ success:false, error:{ code:'ENV_MISCONFIG', message:'DB binding missing' } }), { status:500, headers:{'Content-Type':'application/json'} });
  }
  
  try {
    const processingService = new VideoProcessingService(env);
    const status = await processingService.getProcessingStatus(videoId);
    
    // Also get video status from database
    const video = await env.DB.prepare(
      'SELECT processing_status, duration, thumbnail_url FROM videos WHERE id = ?'
    ).bind(videoId).first();
    
    if (!video) {
      return new Response(
        JSON.stringify({
          success: false,
          error: { code: 'NOT_FOUND', message: 'Video not found' },
        } as ApiResponse),
        {
          status: 404,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    return new Response(
      JSON.stringify({
        success: true,
        data: {
          videoId,
          processingStatus: video.processing_status,
          duration: video.duration,
          thumbnailUrl: video.thumbnail_url,
          jobStatus: status,
        },
      } as ApiResponse),
      {
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Get processing status error:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: { code: 'INTERNAL_ERROR', message: 'Failed to get status' },
      } as ApiResponse),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
};
